class Stroke(list):
    """A brush stroke, plus the size and colour it was drawn with.

    Marks are re-painted from scratch on every render, so without this the
    pen settings were read live and changing the brush size or colour
    retroactively restyled everything already on the canvas. Subclassing
    ``list`` keeps it a plain sequence of points for every other consumer.
    """

    __slots__ = ('thickness', 'color', 'texture', 'stamps', 'flat', 'render', 'history', 'erase',
                 'pic_width', 'clip', 'gpu_render')

    def __init__(self, points=(), thickness=None, color=None, texture=None, stamps=None,
                 flat=False):
        super().__init__(points)
        # 🎮 its render came from the GPU brush (an erase one burns in from it too)
        self.gpu_render = False
        # A round-pen stroke's width in picture pixels as drawn (its layer's
        # image keeps it so); None for older ones and textured strokes.
        self.pic_width = None
        # The outline (picture points) it stays inside, or None: a shape run
        # over with the brush (a mode other than Paint).
        self.clip = None
        # (view transform, image, top-left): the stroke as drawn live, reused
        # while the view is unchanged (see RandomImageViewer._paint_layer_marks).
        self.render = None
        # 🕘 History: the tint (0..1) - the stroke paints the picture back.
        self.history = None
        # 🧽 Erase: the stroke rubs paint out of its layer (only the layer's
        # own image - never the picture or the layers under it).
        self.erase = False
        self.thickness = thickness
        self.color = color
        # A textured brush: the PNG and the stamps laid while drawing (see
        # brushes.StampTrail), and whether they build up (see FlatStroke).
        # The points stay for anything reading the path.
        self.texture = texture
        self.stamps = stamps
        self.flat = flat


def _shift_between(a, b, tol=1e-6):
    """QPoint that moves what transform *a* laid to where *b* lays it, when
    the two differ only by a whole-pixel offset (a pan); else None."""
    lin_a, lin_b = (a.m11(), a.m12(), a.m21(), a.m22()), (b.m11(), b.m12(), b.m21(), b.m22())
    if any(abs(x - y) > tol * max(1.0, abs(x), abs(y)) for x, y in zip(lin_a, lin_b)):
        return None
    dx, dy = b.dx() - a.dx(), b.dy() - a.dy()
    if abs(dx - round(dx)) > 1e-3 or abs(dy - round(dy)) > 1e-3:
        return None
    return QPoint(round(dx), round(dy))


def _same_transform(a, b, tol=1e-6):
    """True when QTransforms *a* and *b* are equal, give or take float noise."""
    return all(abs(x - y) <= tol * max(1.0, abs(x), abs(y)) for x, y in zip(
        (a.m11(), a.m12(), a.m21(), a.m22(), a.dx(), a.dy()),
        (b.m11(), b.m12(), b.m21(), b.m22(), b.dx(), b.dy())))


class _BusyLine(QWidget):
    """A thin line along the bottom of the status bar: work under way in
    the background (marks being laid again after a zoom), filled as far as
    it got. Not in the bar's layout - it lies over its bottom edge."""

    HEIGHT = 3
    FILL = QColor(240, 160, 48)             # the app's amber: it has to be seen

    def __init__(self, bar):
        super().__init__(bar)
        self._bar = bar
        self._fraction = 0.0
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setToolTip("")
        self.hide()

    def show_progress(self, fraction):
        self._fraction = max(0.0, min(1.0, fraction))
        bar = self._bar
        self.setGeometry(0, bar.height() - self.HEIGHT, bar.width(), self.HEIGHT)
        self.raise_()
        if not self.isVisible():
            self.show()
        self.update()

    def paintEvent(self, _event):
        p = QPainter(self)
        p.fillRect(self.rect(), QColor(255, 255, 255, 40))
        p.fillRect(0, 0, round(self.width() * self._fraction), self.height(), self.FILL)
        p.end()


def _still_answering():
    """Long work in the app's own thread: tell Windows the app is alive.
    Without a look at its message queue for 5 s, Windows takes it for hung -
    'not responding', and its windows (this card too) shown as a frozen black
    ghost. A look that takes nothing out (PM_NOREMOVE) - no click or key is
    handled half way through the work."""
    if sys.platform != 'win32':
        return
    try:
        import ctypes
        from ctypes import wintypes
        msg = wintypes.MSG()
        ctypes.windll.user32.PeekMessageW(ctypes.byref(msg), None, 0, 0, 0)
    except Exception:
        pass


class _ProgressCard(QWidget):
    """⏳ A card in the middle of the canvas for work that keeps the app busy
    for a while - saving, opening a project, a shape run over with the
    brush: what it is, how far it got and the step it is on. The work runs
    in the app's own thread, so each change is painted straight away
    (repaint), never left to an event loop that does not come."""

    W, H = 340, 92
    FILL = QColor(240, 160, 48)             # the app's amber, as the busy line

    def __init__(self, viewer):
        super().__init__(viewer, Qt.Tool | Qt.FramelessWindowHint | Qt.WindowDoesNotAcceptFocus)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self._viewer = viewer
        self.title, self.what, self.fraction = "", "", 0.0
        self._shown_at = 0.0
        self.resize(self.W, self.H)
        self.hide()

    def start(self, title):
        self.title, self.what, self.fraction = title, "", 0.0
        self._last = 0.0
        canvas = getattr(self._viewer, 'image_label', None)
        area = (QRect(canvas.mapToGlobal(QPoint(0, 0)), canvas.size())
                if canvas is not None and canvas.isVisible() else self._viewer.frameGeometry())
        self.move(area.center().x() - self.W // 2, area.center().y() - self.H // 2)
        self.show()
        self.raise_()
        self.repaint()
        _still_answering()

    def set(self, fraction, what=None):
        """How far (0..1) and the step it is on; painted at most ~30 times a
        second (the callers report per mark)."""
        self.fraction = max(self.fraction, max(0.0, min(1.0, float(fraction))))
        if what is not None:
            self.what = what
        now = time.monotonic()
        if self.isVisible() and (now - self._last > 0.033 or self.fraction >= 1.0):
            self._last = now
            self.repaint()
            _still_answering()


    def finish(self):
        self.hide()

    def paintEvent(self, _event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        p.setPen(QPen(QColor(255, 255, 255, 30), 1))
        p.setBrush(QColor(30, 31, 34, 238))
        p.drawRoundedRect(QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5), 10, 10)
        m = 16
        font = QFont(self.font())
        font.setPointSizeF(10.5)
        font.setBold(True)
        p.setFont(font)
        p.setPen(QColor(235, 235, 235))
        p.drawText(QRect(m, 12, self.W - 2 * m - 50, 22), Qt.AlignLeft | Qt.AlignVCenter, self.title)
        p.setPen(self.FILL)
        p.drawText(QRect(self.W - m - 60, 12, 60, 22), Qt.AlignRight | Qt.AlignVCenter,
                   f"{self.fraction * 100:.0f}%")
        bar = QRectF(m, 42, self.W - 2 * m, 8)
        p.setPen(Qt.NoPen)
        p.setBrush(QColor(255, 255, 255, 28))
        p.drawRoundedRect(bar, 4, 4)
        if self.fraction > 0:
            p.setBrush(self.FILL)
            p.drawRoundedRect(QRectF(bar.x(), bar.y(), max(8.0, bar.width() * self.fraction), bar.height()), 4, 4)
        font.setBold(False)
        font.setPointSizeF(9)
        p.setFont(font)
        p.setPen(QColor(170, 170, 170))
        p.drawText(QRect(m, 58, self.W - 2 * m, 22), Qt.AlignLeft | Qt.AlignVCenter,
                   QFontMetrics(font).elidedText(self.what, Qt.ElideRight, self.W - 2 * m))
        p.end()


class _PenProximityWatch(QObject):
    """Keeps viewer._pen_near: True from the pen coming near the tablet
    until it leaves (Qt sends the application these, not a widget)."""

    def __init__(self, viewer):
        super().__init__(viewer)
        self._viewer = viewer

    def eventFilter(self, obj, event):
        t = event.type()
        if t == QEvent.TabletEnterProximity:
            self._viewer._pen_near = True
        elif t == QEvent.TabletLeaveProximity:
            self._viewer._pen_near = False
        return False


class _StrokeEndWatch(QObject):
    """A stroke (or erase) left open: the pen or mouse let go somewhere the
    canvas never heard of it - over a panel lying on the canvas (a window of
    its own above the GPU canvas), outside the window, the app losing focus.
    Left open, the app took it for a stroke still under way: two fingers
    would not pan or zoom, the tool kept acting as if drawing - until another
    tool was picked. Any release anywhere, or focus going, ends it."""

    def __init__(self, viewer):
        super().__init__(viewer)
        self._viewer = viewer
        self._queued = False

    def eventFilter(self, obj, event):
        t = event.type()
        if t in (QEvent.TabletRelease, QEvent.MouseButtonRelease, QEvent.ApplicationDeactivate,
                 QEvent.WindowDeactivate, QEvent.TabletLeaveProximity):
            v = self._viewer
            if (getattr(v, 'is_drawing_free_stroke', False) or getattr(v, 'is_erasing', False)) \
                    and not self._queued:
                # after the canvas has had the event (its own release ends it)
                self._queued = True
                QTimer.singleShot(0, self._check)
        return False

    def _check(self):
        self._queued = False
        self._viewer._end_stale_stroke()


class RulerLine(float):
    """A vertical / horizontal ruler line position, plus the size and colour
    it was placed with.

    Same idea as :class:`Stroke`: stored as a bare number the line was
    painted with the live pen, so moving the brush slider resized every ruler
    line already on the canvas. Subclassing ``float`` keeps it a plain
    coordinate for every other consumer (arithmetic, ``in`` checks, undo).
    """

    __slots__ = ('thickness', 'color')

    def __new__(cls, position, thickness=None, color=None):
        obj = super().__new__(cls, position)
        obj.thickness = thickness
        obj.color = color
        return obj


class PdfHiresWorker(QThread):
    """Render a single PDF page (or a 2/3-page spread) at high resolution off
    the GUI thread.

    Emits :attr:`ready` with ``(start_page, count, target, QImage)`` when done.
    A ``QImage`` is produced (not a ``QPixmap``) because only ``QImage`` may be
    built off the main thread; the receiver converts it to a ``QPixmap``.
    """

    ready = Signal(int, int, int, object)

    def __init__(self, pdf_doc, start_page, count, target, parent=None):
        super().__init__(parent)
        self._pdf_doc = pdf_doc
        self._start_page = start_page
        self._count = count
        self._target = target

    def run(self):
        try:
            if self._count > 1:
                img = self._pdf_doc.render_spread_qimage(
                    self._start_page, self._count, self._target)
            else:
                img = self._pdf_doc.render_page_qimage(
                    self._start_page, self._target)
        except Exception as e:
            print(f"PdfHiresWorker error: {e}")
            img = None
        if img is not None:
            self.ready.emit(self._start_page, self._count, self._target, img)


class PdfLoadingOverlay(QWidget):
    """Semi-transparent overlay with a spinning arc and progress text."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, False)
        self.setAutoFillBackground(False)
        self._angle = 0
        self._text = "Loading PDF…"
        self._progress_text = ""
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        if parent:
            parent.installEventFilter(self)
        self.hide()

    # ── public API ──────────────────────────────────────────────
    def start(self, text="Loading PDF…"):
        self._text = text
        self._progress_text = ""
        self._angle = 0
        self._reposition()
        self.show()
        self.raise_()
        self._timer.start(30)  # ~33 fps spinner

    def set_progress(self, done, total):
        pct = int(done / total * 100) if total else 0
        self._progress_text = f"{done} / {total} pages  ({pct}%)"
        self.update()

    def finish(self):
        self._timer.stop()
        self.hide()

    # ── internals ──────────────────────────────────────────────
    def _tick(self):
        self._angle = (self._angle + 5) % 360
        self.update()

    def _reposition(self):
        if self.parent():
            self.setGeometry(self.parent().rect())

    def eventFilter(self, obj, event):
        if obj is self.parent() and event.type() == QEvent.Resize:
            self._reposition()
        return False

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)

        # Dim background
        p.fillRect(self.rect(), QColor(0, 0, 0, 140))

        cx, cy = self.width() // 2, self.height() // 2

        # Spinning arc
        arc_size = min(self.width(), self.height()) // 5
        arc_rect = QRect(cx - arc_size // 2, cy - arc_size // 2 - 20,
                         arc_size, arc_size)
        pen = QPen(QColor(100, 180, 255), 4)
        pen.setCapStyle(Qt.RoundCap)
        p.setPen(pen)
        p.drawArc(arc_rect, self._angle * 16, 270 * 16)

        # Title text
        p.setPen(QColor(255, 255, 255))
        p.setFont(QFont("Segoe UI", 13, QFont.Bold))
        p.drawText(self.rect().adjusted(0, arc_size // 2 + 10, 0, 0),
                   Qt.AlignHCenter | Qt.AlignTop, self._text)

        # Progress text
        if self._progress_text:
            p.setFont(QFont("Segoe UI", 10))
            p.setPen(QColor(180, 180, 180))
            p.drawText(self.rect().adjusted(0, arc_size // 2 + 40, 0, 0),
                       Qt.AlignHCenter | Qt.AlignTop, self._progress_text)

        p.end()


class VideoControlsOverlay(QWidget):
    """Floating translucent video controls panel that appears on mouse hover.

    Sits at the top of the image label (kept clear of bottom-anchored
    subtitles, which it would otherwise visually collide with), auto-hides
    after a few seconds of inactivity — classic video-player behaviour.
    """

    HIDE_DELAY_MS = 2500
    PANEL_HEIGHT = 56
    PANEL_MARGIN = 16

    def __init__(self, parent_label):
        super().__init__(parent_label)
        self._parent_label = parent_label
        self.setAutoFillBackground(False)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setCursor(Qt.ArrowCursor)

        self._opacity = QGraphicsOpacityEffect(self)
        self._opacity.setOpacity(0.0)
        self.setGraphicsEffect(self._opacity)

        self._fade_anim = QPropertyAnimation(self._opacity, b"opacity", self)
        self._fade_anim.setDuration(250)
        self._fade_anim.setEasingCurve(QEasingCurve.InOutQuad)

        self._hide_timer = QTimer(self)
        self._hide_timer.setSingleShot(True)
        self._hide_timer.timeout.connect(self._fade_out)

        self._visible_state = False
        self._duration_ms = 0
        self._position_ms = 0
        self._is_playing = False
        self._is_muted = False
        self._viewer = None

        self._build_ui()
        # Preview card for the position under the pointer (see _on_hover_time)
        self._thumb = ThumbnailPopup(parent_label)
        self._thumb_ms = None
        self._thumb_x = 0
        self.hide()
        parent_label.installEventFilter(self)

    # ── build UI ──────────────────────────────────────────────
    def _build_ui(self):
        self.setStyleSheet("VideoControlsOverlay { background: transparent; }")
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        container = QWidget(self)
        container.setObjectName("vco_container")
        container.setStyleSheet("""
            #vco_container {
                background: rgba(20, 20, 20, 200);
                border-radius: 10px;
            }
            QLabel { color: #ddd; font-size: 11px; }
            QToolButton {
                color: #ddd; background: transparent;
                border: none; font-size: 14px;
            }
            QToolButton:hover {
                background: rgba(255,255,255,40);
                border-radius: 4px;
            }
            QToolButton:checked {
                background: rgba(100, 180, 255, 170);
                border-radius: 4px;
            }
            QToolButton:disabled { color: #777; }
            QSlider::groove:horizontal {
                height: 6px;
                background: rgba(255,255,255,50);
                border-radius: 3px;
            }
            QSlider::handle:horizontal {
                background: #fff;
                width: 14px; height: 14px;
                margin: -4px 0;
                border-radius: 7px;
            }
            QSlider::sub-page:horizontal {
                background: rgba(100, 180, 255, 200);
                border-radius: 3px;
            }
        """)

        c_layout = QVBoxLayout(container)
        c_layout.setContentsMargins(12, 6, 12, 8)
        c_layout.setSpacing(4)

        self._seek_slider = SeekSlider(Qt.Horizontal)
        self._seek_slider.setRange(0, 0)
        self._seek_slider.setFixedHeight(18)
        self._seek_slider.sliderMoved.connect(self._on_seek)
        self._seek_slider.hover_time.connect(self._on_hover_time)
        self._seek_slider.hover_left.connect(self.hide_thumbnail)
        c_layout.addWidget(self._seek_slider)

        ctrl_row = QHBoxLayout()
        ctrl_row.setSpacing(6)

        self._play_btn = QToolButton()
        self._play_btn.setText("\u25b6")
        self._play_btn.setFixedSize(28, 28)
        self._play_btn.clicked.connect(self._on_play_pause)
        ctrl_row.addWidget(self._play_btn)

        self._time_label = QLabel("0:00 / 0:00")
        self._time_label.setFixedHeight(22)
        ctrl_row.addWidget(self._time_label)

        ctrl_row.addStretch()

        # Autoplay next / dub audio also live on the main toolbar, but that is
        # hidden in minimal and panel layouts — mirror them here so they are
        # reachable whenever a video is on screen.
        self._loop_btn = QToolButton()
        self._loop_btn.setText("\U0001f501")
        self._loop_btn.setCheckable(True)
        self._loop_btn.setToolTip("Loop: play this video or GIF again when it ends")
        self._loop_btn.setFixedSize(28, 28)
        self._loop_btn.clicked.connect(self._on_loop_toggle)
        ctrl_row.addWidget(self._loop_btn)

        self._autoplay_btn = QToolButton()
        self._autoplay_btn.setText("\u23ed")
        self._autoplay_btn.setCheckable(True)
        self._autoplay_btn.setToolTip(
            "Autoplay next: advance when this video or GIF finishes")
        self._autoplay_btn.setFixedSize(28, 28)
        self._autoplay_btn.clicked.connect(self._on_autoplay_toggle)
        ctrl_row.addWidget(self._autoplay_btn)

        self._subs_btn = QToolButton()
        self._subs_btn.setText("\U0001f4ac")
        self._subs_btn.setCheckable(True)
        self._subs_btn.setFixedSize(28, 28)
        self._subs_btn.clicked.connect(self._on_subs_toggle)
        ctrl_row.addWidget(self._subs_btn)

        self._dub_btn = QToolButton()
        self._dub_btn.setText("\U0001f3b5")
        self._dub_btn.setCheckable(True)
        self._dub_btn.setToolTip(
            "Dub audio: play a sibling audio file with the same name "
            "(clip.mp4 \u2192 clip.mp3) instead of the video's own track")
        self._dub_btn.setFixedSize(28, 28)
        self._dub_btn.clicked.connect(self._on_dub_toggle)
        ctrl_row.addWidget(self._dub_btn)

        self._mute_btn = QToolButton()
        self._mute_btn.setText("\U0001f50a")
        self._mute_btn.setFixedSize(28, 28)
        self._mute_btn.clicked.connect(self._on_mute_toggle)
        ctrl_row.addWidget(self._mute_btn)

        self._volume_slider = QSlider(Qt.Horizontal)
        self._volume_slider.setRange(0, 100)
        self._volume_slider.setValue(50)
        self._volume_slider.setFixedWidth(70)
        self._volume_slider.setFixedHeight(18)
        self._volume_slider.valueChanged.connect(self._on_volume)
        ctrl_row.addWidget(self._volume_slider)

        c_layout.addLayout(ctrl_row)
        layout.addWidget(container)

    # ── public API (called by MainWindow) ───────────────────────
    def set_viewer(self, viewer):
        self._viewer = viewer

    def activate(self, volume=50, muted=False):
        """Show the overlay and prepare for a new video."""
        self._duration_ms = 0
        self._position_ms = 0
        self._is_playing = True
        self._is_muted = muted
        self._volume_slider.blockSignals(True)
        self._volume_slider.setValue(volume)
        self._volume_slider.blockSignals(False)
        self._mute_btn.setText("\U0001f507" if muted else "\U0001f50a")
        if self._viewer is not None:
            self.update_autoplay_state(getattr(self._viewer, 'autoplay_next_enabled', False))
            self.update_loop_state(getattr(self._viewer, 'loop_media_enabled', False))
            self.update_dub_state(getattr(self._viewer, 'dub_audio_enabled', False))
            self.update_subtitle_state(
                bool(getattr(self._viewer, '_subtitle_cues', None)),
                getattr(self._viewer, '_subtitles_enabled', True),
                os.path.basename(getattr(self._viewer, '_subtitle_path', '') or '') or None)
        self._play_btn.setText("\u23f8")
        self._time_label.setText("0:00 / 0:00")
        self._seek_slider.setRange(0, 0)
        self._reposition()
        self.show()
        self.raise_()
        self._fade_in()

    def deactivate(self):
        self.hide_thumbnail()
        self._hide_timer.stop()
        self._fade_anim.stop()
        self._opacity.setOpacity(0.0)
        self.hide()
        self._visible_state = False

    def update_duration(self, ms):
        self._duration_ms = ms
        self._seek_slider.setRange(0, max(ms, 0))
        self._update_time_text()

    def update_position(self, ms):
        self._position_ms = ms
        if not self._seek_slider.isSliderDown():
            self._seek_slider.setValue(ms)
        self._update_time_text()

    def update_play_state(self, playing):
        self._is_playing = playing
        self._play_btn.setText("\u23f8" if playing else "\u25b6")

    def update_mute_state(self, muted):
        self._is_muted = muted
        self._mute_btn.setText("\U0001f507" if muted else "\U0001f50a")

    def update_loop_state(self, enabled):
        """Mirror the toolbar's loop toggle."""
        self._loop_btn.blockSignals(True)
        self._loop_btn.setChecked(bool(enabled))
        self._loop_btn.blockSignals(False)

    def update_autoplay_state(self, enabled):
        """Mirror the toolbar's autoplay-next toggle."""
        self._autoplay_btn.blockSignals(True)
        self._autoplay_btn.setChecked(bool(enabled))
        self._autoplay_btn.blockSignals(False)

    def update_subtitle_state(self, available, enabled, name=None):
        """Mirror subtitle availability and on/off state.

        A video with no sibling .srt greys the button out rather than hiding
        it, so the control does not jump around between clips.
        """
        self._subs_btn.setEnabled(bool(available))
        self._subs_btn.blockSignals(True)
        self._subs_btn.setChecked(bool(available) and bool(enabled))
        self._subs_btn.blockSignals(False)
        if not available:
            self._subs_btn.setToolTip("Subtitles: no matching .srt beside this video")
        elif enabled:
            self._subs_btn.setToolTip(
                f"Subtitles: showing {name} (click to hide)" if name
                else "Subtitles: on (click to hide)")
        else:
            self._subs_btn.setToolTip(
                f"Subtitles: {name} hidden (click to show)" if name
                else "Subtitles: off (click to show)")

    def update_dub_state(self, enabled, detail=None):
        """Mirror the toolbar's dub-audio toggle; *detail* names the track."""
        self._dub_btn.blockSignals(True)
        self._dub_btn.setChecked(bool(enabled))
        self._dub_btn.blockSignals(False)
        if detail:
            self._dub_btn.setToolTip(
                f"Dub audio: playing {detail} (click to use the video's own track)")
        elif enabled:
            self._dub_btn.setToolTip(
                "Dub audio: on \u2014 no matching audio file beside this video")
        else:
            self._dub_btn.setToolTip(
                "Dub audio: play a sibling audio file with the same name "
                "(clip.mp4 \u2192 clip.mp3) instead of the video's own track")

    # ── internal ──────────────────────────────────────────────
    def _update_time_text(self):
        cur = self._fmt(self._position_ms)
        tot = self._fmt(self._duration_ms)
        self._time_label.setText(f"{cur} / {tot}")

    @staticmethod
    def _fmt(ms):
        s = max(0, ms) // 1000
        m, s = divmod(s, 60)
        h, m = divmod(m, 60)
        return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"

    def _reposition(self):
        if self._parent_label:
            pw = self._parent_label.width()
            w = pw - 2 * self.PANEL_MARGIN
            if w < 200:
                w = pw
            x = (pw - w) // 2
            y = 10
            self.setGeometry(x, y, w, self.PANEL_HEIGHT)

    def _fade_in(self):
        self._fade_anim.stop()
        self._fade_anim.setStartValue(self._opacity.opacity())
        self._fade_anim.setEndValue(0.95)
        self._fade_anim.start()
        self._visible_state = True
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _fade_out(self):
        if self._seek_slider.isSliderDown() or self._volume_slider.isSliderDown():
            self._hide_timer.start(self.HIDE_DELAY_MS)
            return
        self.hide_thumbnail()
        self._fade_anim.stop()
        self._fade_anim.setStartValue(self._opacity.opacity())
        self._fade_anim.setEndValue(0.0)
        self._fade_anim.start()
        self._visible_state = False

    # ── hover preview ─────────────────────────────────────────
    def _on_hover_time(self, ms, x):
        """Pointer over the timeline: show that time, and the frame there."""
        if self._duration_ms <= 0:
            return
        if self._thumb_ms is None or abs(ms - self._thumb_ms) >= 1000:
            self._thumb.clear_frame()      # another second: drop the stale frame
        self._thumb_ms = ms
        self._thumb.set_text(self._fmt(ms))
        self._place_thumbnail(x)
        self._hide_timer.start(self.HIDE_DELAY_MS)   # keep the panel up while hovering
        if self._viewer is not None:
            self._viewer.request_video_thumbnail(ms)

    def show_thumbnail(self, ms, image):
        """A decoded frame arrived; ignore it if the pointer has moved on."""
        if self._thumb_ms is None or abs(ms - self._thumb_ms) >= 1000:
            return
        self._thumb.set_frame(image)
        self._place_thumbnail(self._thumb_x)

    def hide_thumbnail(self):
        self._thumb_ms = None
        self._thumb.hide()

    def _place_thumbnail(self, x):
        """Centre the card on the pointer, just below the panel."""
        self._thumb_x = x
        label = self._parent_label
        if label is None:
            return
        pos = self._seek_slider.mapTo(label, QPoint(int(x), 0))
        w, h = self._thumb.width(), self._thumb.height()
        left = max(4, min(pos.x() - w // 2, max(4, label.width() - w - 4)))
        top = self.y() + self.height() + 6
        if top + h > label.height():        # no room below: sit above the panel
            top = max(4, self.y() - h - 6)
        self._thumb.move(int(left), int(top))
        self._thumb.show()
        self._thumb.raise_()

    def _on_seek(self, pos):
        if self._viewer:
            self._viewer.image_label.video_seek(pos)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_play_pause(self):
        if self._viewer:
            self._viewer.image_label.video_toggle_play_pause()
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_mute_toggle(self):
        if self._viewer:
            self._viewer._toggle_video_mute()
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_subs_toggle(self, checked):
        if self._viewer:
            self._viewer.toggle_subtitles(checked)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_loop_toggle(self, checked):
        if self._viewer:
            self._viewer.toggle_loop_media(checked)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_autoplay_toggle(self, checked):
        if self._viewer:
            self._viewer.toggle_autoplay_next(checked)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_dub_toggle(self, checked):
        if self._viewer:
            self._viewer.toggle_dub_audio(checked)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    def _on_volume(self, val):
        if self._viewer:
            self._viewer._on_video_volume_changed(val)
        self._hide_timer.start(self.HIDE_DELAY_MS)

    # ── event filter: track mouse on parent label ─────────────
    def eventFilter(self, obj, event):
        if obj is self._parent_label:
            etype = event.type()
            if etype == QEvent.MouseMove:
                if self.isVisible() and self._viewer and self._viewer._video_playing:
                    self._reposition()
                    if not self._visible_state:
                        self._fade_in()
                    else:
                        self._hide_timer.start(self.HIDE_DELAY_MS)
            elif etype == QEvent.Resize:
                self._reposition()
            elif etype == QEvent.Enter:
                if self.isVisible() and self._viewer and self._viewer._video_playing:
                    self._fade_in()
            elif etype == QEvent.Leave:
                if self._visible_state:
                    self._hide_timer.start(800)
        return False

    def enterEvent(self, event):
        self._hide_timer.stop()
        if not self._visible_state:
            self._fade_in()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hide_timer.start(self.HIDE_DELAY_MS)
        super().leaveEvent(event)


class RandomImageViewer(QMainWindow):
    # Small toolbar spin boxes: hide the arrow buttons so the number shows.
    _SPIN_NO_ARROWS = "QSpinBox::up-button, QSpinBox::down-button { width: 0px; border: none; }"

    # ...existing code...
    def _create_overlay_icon(self, icon_type):
        """Create a QPainter-drawn icon for overlay tool buttons.
        icon_type: 'crosshair' or 'grid'
        """
        size = 18
        img = QImage(size, size, QImage.Format_ARGB32)
        img.fill(Qt.transparent)
        p = QPainter(img)
        p.setRenderHint(QPainter.Antialiasing, False)
        pen = QPen(QColor("#c8c8c8"), 1, Qt.SolidLine)
        p.setPen(pen)

        if icon_type == 'crosshair':
            cx, cy = size // 2, size // 2
            gap = 3  # gap around center
            # Vertical arm: top segment + bottom segment
            p.drawLine(cx, 0, cx, cy - gap)
            p.drawLine(cx, cy + gap, cx, size - 1)
            # Horizontal arm: left segment + right segment
            p.drawLine(0, cy, cx - gap, cy)
            p.drawLine(cx + gap, cy, size - 1, cy)
        elif icon_type == 'crossgrid':
            # ✛ small crosses in a 3 x 3 grid
            for cx in (3, 9, 15):
                for cy in (3, 9, 15):
                    p.drawLine(cx - 2, cy, cx + 2, cy)
                    p.drawLine(cx, cy - 2, cx, cy + 2)
        elif icon_type == 'grid':
            # Outer border
            p.drawRect(0, 0, size - 1, size - 1)
            # Two vertical dividers at 1/3 and 2/3
            v1 = size // 3
            v2 = (size * 2) // 3
            p.drawLine(v1, 0, v1, size - 1)
            p.drawLine(v2, 0, v2, size - 1)
            # Two horizontal dividers at 1/3 and 2/3
            h1 = size // 3
            h2 = (size * 2) // 3
            p.drawLine(0, h1, size - 1, h1)
            p.drawLine(0, h2, size - 1, h2)

        p.end()
        return QIcon(QPixmap.fromImage(img))

    def _guide_pen(self):
        """A copy of the current pen, for a guide being switched on.

        Guides keep it from then on, the way lines keep the size and colour
        they were drawn with, so the brush slider and colour picker only
        affect what you draw next. Switch a guide off and on to restyle it.
        """
        return QPen(QColor(self.line_color), max(1, int(self.line_thickness)), Qt.SolidLine)

    def _draw_fixed_overlays(self, painter, draw_x, draw_y, zoomed_width, zoomed_height):
        """Draw crosshair and/or 3x3 grid overlay onto an already-active QPainter.
        Coordinates are in display/pixmap space.
        """
        if self.crosshair_overlay:
            painter.setPen(self._crosshair_pen or self._guide_pen())
            cx = draw_x + zoomed_width // 2
            cy = draw_y + zoomed_height // 2
            # Full-length vertical and horizontal cross through image center
            painter.drawLine(cx, draw_y, cx, draw_y + zoomed_height)
            painter.drawLine(draw_x, cy, draw_x + zoomed_width, cy)

        if self._comp_grids:
            from random_image_viewer.drawing import comp_grids
            grids = list(self._comp_grids.items())
            points = self.__dict__.get('_grid_points') or {}
            for rect in self._comp_grid_rects(draw_x, draw_y, zoomed_width, zoomed_height):
                comp_grids.paint_grids(painter, rect, grids, opacity=self._comp_grid_opacity / 100.0,
                                       params=points)
            self._draw_grid_handles(painter, draw_x, draw_y, zoomed_width, zoomed_height)

    # -- ▦ moving a perspective grid's vanishing points ---------------------
    #
    # While the ▦ grids palette is open, each perspective grid shows its
    # points (vanishing points, the fisheye's centre) as handles to drag -
    # pen or mouse; right-click one: back where it was. A point off the
    # view sits at its edge, a short line pointing to where it really is,
    # and is dragged from there. Closed palette: no handles, nothing in the
    # way of painting. Kept per grid as fractions of the picture (see
    # comp_grids.POINTS), saved with the settings.

    _GRID_HANDLE_R = 7          # px: the handle's radius ...
    _GRID_HANDLE_GRAB = 13      # ... and how near grabs it

    def _grid_handles_on(self):
        win = self.__dict__.get('_grids_window')
        return bool(win is not None and win.isVisible() and self._comp_grids
                    and getattr(self, 'lines_visible', True))

    def _grid_handles(self):
        """[(key, index, true point, shown point, rect, orient)] - label
        coords; *shown* is the true point kept inside the view."""
        if not self._grid_handles_on():
            return []
        from random_image_viewer.drawing import comp_grids
        tx = self._compute_line_transform()
        if not tx:
            return []
        label = self.image_label
        m = self._GRID_HANDLE_R + 4
        view = QRectF(m, m, max(1, label.width() - 2 * m), max(1, label.height() - 2 * m))
        stored = self.__dict__.get('_grid_points') or {}
        out = []
        rects = self._comp_grid_rects(tx['draw_x'], tx['draw_y'], tx['zoomed_width'], tx['zoomed_height'])
        for key, orient in self._comp_grids.items():
            pts = comp_grids.points(key, stored.get(key))
            if not pts:
                continue
            for rect in rects[:1]:          # (◧ Studio: on the canvas half)
                for i, f in enumerate(pts):
                    x, y = comp_grids.point_on(rect, orient, f)
                    shown = QPointF(min(max(x, view.left()), view.right()),
                                    min(max(y, view.top()), view.bottom()))
                    out.append((key, i, QPointF(x, y), shown, rect, orient))
        return out

    def _draw_grid_handles(self, painter, draw_x, draw_y, zoomed_width, zoomed_height):
        handles = self._grid_handles()
        if not handles:
            return
        from random_image_viewer.drawing import comp_grids
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        r = self._GRID_HANDLE_R
        held = self.__dict__.get('_grid_drag')
        for key, i, true, shown, _rect, _o in handles:
            colour = comp_grids.colour(key, 1.0)
            off = (true - shown).manhattanLength() > 0.5
            if off:
                # off the view: a short line from the handle towards it
                d = true - shown
                n = math.hypot(d.x(), d.y()) or 1.0
                tip = shown + QPointF(d.x() / n, d.y() / n) * (r + 9)
                for pen in (QPen(QColor(0, 0, 0, 200), 3.2), QPen(colour, 1.6)):
                    painter.setPen(pen)
                    painter.drawLine(shown, tip)
            grabbed = held is not None and held[0] == key and held[1] == i
            painter.setPen(QPen(QColor(0, 0, 0, 210), 3.0))
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(shown, r, r)
            painter.setPen(QPen(QColor(255, 255, 255, 240), 1.4))
            painter.setBrush(QColor(colour.red(), colour.green(), colour.blue(), 230 if grabbed else 150))
            painter.drawEllipse(shown, r, r)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor(255, 255, 255))
            painter.drawEllipse(shown, 1.6, 1.6)
        painter.restore()

    def grid_handle_at(self, pos):
        """The handle under *pos* (label coords): (key, index, ...), or None."""
        best = None
        for h in self._grid_handles():
            d = math.hypot(h[3].x() - pos.x(), h[3].y() - pos.y())
            if d <= self._GRID_HANDLE_GRAB and (best is None or d < best[0]):
                best = (d, h)
        return best[1] if best else None

    def grid_handle_press(self, pos, button=Qt.LeftButton):
        """A press on a handle: dragged from here on (right-click: that
        grid's points back to their defaults). True when taken."""
        h = self.grid_handle_at(pos)
        if h is None:
            return False
        key, i, true, shown, rect, orient = h
        if button == Qt.RightButton:
            pts = self.__dict__.get('_grid_points') or {}
            pts.pop(key, None)
            self._grid_points = pts
            self._save_grid_points()
            self._refresh_grid_view()
            self.status.showMessage("▦ Perspective points back to where they were", 2500)
            return True
        # (grabbed off the view: the point jumps to the pen, then follows it)
        self._grid_drag = (key, i, rect, orient, true - shown if (true - shown).manhattanLength() < 0.5
                           else QPointF(0, 0))
        self.image_label.setCursor(Qt.ClosedHandCursor)
        self._refresh_grid_view()
        return True

    def grid_handle_move(self, pos):
        drag = self.__dict__.get('_grid_drag')
        if drag is None:
            return False
        from random_image_viewer.drawing import comp_grids
        key, i, rect, orient, _off = drag
        stored = self.__dict__.get('_grid_points') or {}
        pts = comp_grids.points(key, stored.get(key))
        fx, fy = comp_grids.fraction_of(rect, orient, pos.x(), pos.y())
        pts[i] = (fx, fy)
        if key in comp_grids.HORIZON_PAIR and i in (0, 1):
            pts[1 - i] = (pts[1 - i][0], fy)            # one horizon
        stored[key] = [list(p) for p in pts]
        self._grid_points = stored
        now = time.monotonic()
        if now - self.__dict__.get('_grid_drag_paint', 0.0) > 0.016:
            self._grid_drag_paint = now
            self._refresh_grid_view(live=True)
        return True

    def grid_handle_release(self):
        if self.__dict__.pop('_grid_drag', None) is None:
            return False
        self._save_grid_points()
        self.apply_tool_cursor()
        self._refresh_grid_view()
        return True

    def _save_grid_points(self):
        try:
            self._settings.setValue("comp_grid_points", json.dumps(self.__dict__.get('_grid_points') or {}))
        except Exception as e:
            print(f"▦ grid points not saved: {e!r}")

    def _load_grid_points(self):
        try:
            raw = json.loads(str(self._settings.value("comp_grid_points", "") or "{}"))
            return {k: [[float(x), float(y)] for x, y in v] for k, v in raw.items()}
        except Exception:
            return {}

    def _refresh_grid_view(self, live=False):
        """The grids drawn again: on the GPU canvas a repaint (they are its
        overlay), else the view made again."""
        gpu = self.__dict__.get('_gpu_canvas')
        if self.__dict__.get('_gpu_display') and gpu is not None and getattr(gpu, 'active', False):
            gpu._full = True
            gpu.update()
            return
        if live and not self.current_image:
            return
        self.enhancement_cache.clear()
        self.scaled_cache.clear()
        if self.current_image:
            self.display_image(self.current_image)

    def _comp_grid_rects(self, draw_x, draw_y, zoomed_width, zoomed_height):
        """Where the ▦ grids go (display coords): the picture - in ◧ Studio
        each half, the canvas and the picture, the same grid on both (the
        study and its model measured alike)."""
        from PySide6.QtCore import QRectF
        whole = [QRectF(draw_x, draw_y, zoomed_width, zoomed_height)]
        if not self.studio_mode or not self.current_image:
            return whole
        base = self.pixmap_cache.get(self.current_image)
        if base is None or base.isNull():
            return whole
        offset = self._studio_offset(base)
        sheet = offset + base.width()
        if self.rotation_angle % 180 == 0:
            k = zoomed_width / sheet
            return [QRectF(draw_x, draw_y, base.width() * k, zoomed_height),
                    QRectF(draw_x + offset * k, draw_y, base.width() * k, zoomed_height)]
        k = zoomed_height / sheet           # turned a quarter: the halves one above the other
        return [QRectF(draw_x, draw_y, zoomed_width, base.width() * k),
                QRectF(draw_x, draw_y + offset * k, zoomed_width, base.width() * k)]

    def _fixed_overlays_on(self):
        """Something is laid over the finished view: crosshair, ▦ grids, or
        ◧🔒 the clean reference."""
        return bool(self.crosshair_overlay or self.grid_overlay or self._clean_reference_on())

    def _clean_reference_on(self):
        """◧🔒 Studio keeps the picture clean: effects, blends and anything
        on a layer go to the canvas, the picture is shown as it is."""
        path = self.current_image
        return bool(self.studio_mode and getattr(self, 'studio_ref_clean', False) and path
                    and self.image_visible and not is_video_file(path) and not is_animated_image(path)
                    and getattr(self, '_pdf_doc', None) is None)

    def _clean_reference_view(self):
        """The plain Studio sheet fitted to the view exactly as the display
        fits it (turned, scaled, placed - _scale_pixmap_now), no effects, no
        marks. Kept while the view stays. (Laid through the marks' transform
        instead, the picture came out ~2 px wider than the display's own.)"""
        base = self.pixmap_cache.get(self.current_image)
        if base is None or base.isNull():
            return None, None
        sheet = self._studio_sheet(base)
        label = self.image_label
        size = label.size()
        key = (sheet.cacheKey(), size.width(), size.height(), label.zoom_factor,
               label.pan_offset_x, label.pan_offset_y, self.rotation_angle, self.flipped_h,
               self.flipped_v, self.canvas_color.rgba(), self._picture_look())
        kept = self.__dict__.get('_clean_ref_kept')
        if kept is None or kept[0] != key:
            turned = self._apply_cached_transforms(sheet)
            view = self._scale_pixmap_now(turned, size, label.zoom_factor,
                                          label.pan_offset_x, label.pan_offset_y)
            kept = self._clean_ref_kept = (key, view)
        return base, kept[1]

    def _draw_clean_reference(self, painter):
        """◧🔒 The picture, untouched, laid over its half of the Studio sheet -
        whatever the effects, a layer's blend or a mark did there is covered."""
        if getattr(self, 'original_pixmap', None) is None:
            return
        base, view = self._clean_reference_view()
        tx = self._compute_line_transform()
        if view is None or not tx:
            return
        try:
            original_size = self.original_pixmap.size()
            if self.rotation_angle in (90, 270):
                unrot_w, unrot_h = original_size.height(), original_size.width()
            else:
                unrot_w, unrot_h = original_size.width(), original_size.height()
            to_view = self._picture_to_display(
                self._mark_display_mapper(original_size, tx['scale_x'], tx['scale_y'],
                                          tx['draw_x'], tx['draw_y']), unrot_w, unrot_h)
            # where the picture's half is: its rect, a few px over into the
            # gap (the clean view has the same gap there)
            area = to_view.mapRect(QRectF(self._studio_offset(base), 0, base.width(),
                                          base.height())).adjusted(-4, -4, 4, 4)
        except Exception:
            return
        painter.save()
        painter.setClipRect(area)
        painter.setCompositionMode(QPainter.CompositionMode_SourceOver)
        painter.setOpacity(1.0)
        painter.drawPixmap(0, 0, view)
        painter.restore()

    def _apply_fixed_overlays_to_pixmap(self, pixmap):
        """Apply crosshair/grid overlay on top of pixmap (display space).
        Returns a copy with overlays painted, or the original if nothing to draw.
        """
        clean = self._clean_reference_on()
        if not (self.crosshair_overlay or self.grid_overlay or clean):
            return pixmap
        if not getattr(self, 'lines_visible', True) and not clean:
            return pixmap
        if not pixmap or pixmap.isNull():
            return pixmap

        tx = self._compute_line_transform()
        if not tx:
            return pixmap

        result = pixmap.copy()
        painter = QPainter(result)
        painter.setRenderHint(QPainter.Antialiasing, False)
        if clean:
            self._draw_clean_reference(painter)
        if getattr(self, 'lines_visible', True):
            self._draw_fixed_overlays(
                painter,
                tx['draw_x'], tx['draw_y'],
                tx['zoomed_width'], tx['zoomed_height']
            )
        painter.end()
        return result

    def _compute_line_transform(self):
        """Compute scaling and offset for mapping original image coords to current displayed pixmap.
        Returns dict with scale_x, scale_y, draw_x, draw_y. Now supports rotation and flips."""
        try:
            if not hasattr(self, 'original_pixmap') or not self.original_pixmap:
                return None
            if not self.image_label or not self.image_label.pixmap():
                return None
            
            original_size = self.original_pixmap.size()
            label_size = self.image_label.size()
            zoom_factor = getattr(self.image_label, 'zoom_factor', 1.0)
            
            # original_pixmap has already had the rotation applied, so its size
            # *is* the display reference. Swapping it here (as this used to do)
            # produced a width measured on the rotated image divided by the
            # unrotated one, which put annotations on a 90/270 image at a
            # different scale than display_image used for the very same marks.
            display_reference_size = original_size
            
            # Base scaled size at 100% (aspect fit) using the correct reference dimensions
            base_scaled = display_reference_size.scaled(label_size, Qt.KeepAspectRatio)
            zoomed_width = int(base_scaled.width() * zoom_factor)
            zoomed_height = int(base_scaled.height() * zoom_factor)
            draw_x = (label_size.width() - zoomed_width) // 2 + int(getattr(self.image_label, 'pan_offset_x', 0))
            draw_y = (label_size.height() - zoomed_height) // 2 + int(getattr(self.image_label, 'pan_offset_y', 0))
            scale_x = zoomed_width / original_size.width() if original_size.width() else 1.0
            scale_y = zoomed_height / original_size.height() if original_size.height() else 1.0
            return {
                'scale_x': scale_x,
                'scale_y': scale_y,
                'draw_x': draw_x,
                'draw_y': draw_y,
                'zoomed_width': zoomed_width,
                'zoomed_height': zoomed_height
            }
        except Exception as e:
            print(f"_compute_line_transform error: {e}")
            return None
    # ───────────── Annotation painting (single source of truth) ─────────────
    #
    # Every mark the user makes is stored in original-image coordinates and
    # painted on top of the processed picture. Rotation, flips, scale and the
    # letterbox offset all have to be re-applied here, and that math used to be
    # copy-pasted into fifteen render blocks across _fast_line_update(),
    # display_image() and _smart_zoom_display(). The helpers below are the one
    # place it lives now, so a new mark type only has to be taught once.

    def _mark_display_mapper(self, original_size, scale_x, scale_y, offset_x, offset_y):
        """Return f(x, y) mapping original-image coords to display coords."""
        rot = self.rotation_angle
        flip_h = self.flipped_h
        flip_v = self.flipped_v
        # Marks are stored against the *unrotated* picture, but original_size is
        # the already-rotated pixmap, so un-swap it before using it to mirror.
        # Getting this wrong flips around the short edge on a 90/270 image.
        if rot in (90, 270):
            unrot_w, unrot_h = original_size.height(), original_size.width()
        else:
            unrot_w, unrot_h = original_size.width(), original_size.height()

        def to_display(x, y):
            fx = (unrot_w - x) if flip_h else x
            fy = (unrot_h - y) if flip_v else y
            if rot == 90:
                return int((unrot_h - fy) * scale_x) + offset_x, int(fx * scale_y) + offset_y
            if rot == 180:
                return int((unrot_w - fx) * scale_x) + offset_x, int((unrot_h - fy) * scale_y) + offset_y
            if rot == 270:
                return int(fy * scale_x) + offset_x, int((unrot_w - fx) * scale_y) + offset_y
            return int(fx * scale_x) + offset_x, int(fy * scale_y) + offset_y

        return to_display

    def _ordered_marks(self, layer):
        """Yield ``(kind, payload)`` for every mark of *layer* in the order it was made.

        ``_undo_stack`` already records the kind of each mark chronologically
        (it is what Ctrl+Z walks), so replaying it alongside a per-kind cursor
        recovers true creation order across all types. If the stack and the
        lists ever disagree — an older session, or a mark added without a stack
        entry — whatever is left over is emitted afterwards in list order, so
        nothing is silently dropped.
        """
        marks = layer.marks
        buckets = {
            'line': list(marks['drawn_lines']),
            'hline': list(marks['drawn_horizontal_lines']),
            'free_line': list(marks['drawn_free_lines']),
            'free_stroke': list(marks['drawn_free_strokes']),
            'fill': list(marks['drawn_fills']),
            'image': list(marks['drawn_images']),
            'erase': list(marks['erase_strokes']),
        }
        cursor = {k: 0 for k in buckets}
        for kind in marks['_undo_stack']:
            items = buckets.get(kind)
            if items is None:
                continue  # anything this painter does not draw
            i = cursor[kind]
            if i < len(items):
                cursor[kind] = i + 1
                yield kind, items[i]
        for kind, items in buckets.items():
            for item in items[cursor[kind]:]:
                yield kind, item

    def _paint_marks(self, painter, canvas_width, canvas_height, original_size,
                     scale_x, scale_y, offset_x=0, offset_y=0, which=None):
        """Paint every visible layer onto *painter*, bottom to top.

        Each layer goes through a transparent image of the painter's device,
        which is then blended on as one piece. On screen that image is kept (see
        _layer_image), so a drawing costs the same however much of it there is.
        A caller that paints scaled (the crop does) gets a one-off image with
        its transform, or none where the layer needs none. *which*: only the
        layers it accepts (a callable) - those under or over the effects.
        """
        view = (canvas_width, canvas_height, original_size, scale_x, scale_y, offset_x, offset_y)
        # The canvas under the picture, where the hidden picture would be -
        # under every layer. Effects treat it like the picture.
        sheet = self._under_sheet_layer()
        if sheet is not None and (which is None or which(sheet)) and not self._export_no_paper:
            self._paint_layer_fill(painter, sheet, view)
        if not self.lines_visible:
            return
        on_screen = painter.worldTransform().isIdentity() and not self._exporting
        # 🖼 Picture hidden: the layers blend with each other (Overlay on the
        # painting below), on a transparent stack that then goes over the
        # flat background as it is - blending with a black background would
        # swallow a Multiply layer whole.
        target = painter
        stack = None
        if not self.image_visible and any(
                layer.visible and layer.blend != 'Normal' and layer.has_content()
                for layer in self.layers if which is None or which(layer)):
            device = painter.device()
            stack = QImage(device.width(), device.height(), QImage.Format_ARGB32_Premultiplied)
            stack.fill(Qt.transparent)
            painter = QPainter(stack)
            painter.setRenderHints(target.renderHints())
            painter.setWorldTransform(target.worldTransform())
        try:
            self._paint_layer_stack(painter, view, on_screen, which, blend=stack is not None)
        finally:
            if stack is not None:
                painter.end()
                target.save()
                target.resetTransform()
                target.drawImage(0, 0, stack)
                target.restore()

    def _paint_layer_stack(self, painter, view, on_screen, which, blend):
        """The layers of _paint_marks, bottom to top. *blend*: their blend
        modes apply even with the picture hidden (painting on a stack)."""
        canvas_width, canvas_height, original_size, scale_x, scale_y, offset_x, offset_y = view
        for layer in self.layers:
            if not layer.visible or not layer.has_content():
                continue
            if which is not None and not which(layer):     # see _fx_composite
                continue
            erasing = layer is self.active_layer and self.current_erase_stroke
            rubbing = (self._live_rub_image(painter.device()) if on_screen
                       and layer is self.active_layer else None)
            if not on_screen and layer.is_plain() and not erasing:
                self._paint_layer_marks(painter, self._ordered_marks(layer), *view)
                continue
            device = painter.device()
            if on_screen:
                image = self._layer_image(layer, device, view)
            else:
                image = QImage(device.width(), device.height(), QImage.Format_ARGB32_Premultiplied)
                image.fill(Qt.transparent)
                layer_painter = QPainter(image)
                layer_painter.setWorldTransform(painter.worldTransform())
                if layer.fill is not None and not self._export_no_paper:
                    self._paint_layer_fill(layer_painter, layer, view)
                self._paint_layer_marks(layer_painter, self._ordered_marks(layer), *view)
                layer_painter.end()
            if erasing:
                # Live, so on a copy: the stroke is not a mark until it ends.
                image = image.copy()
                layer_painter = QPainter(image)
                layer_painter.setWorldTransform(painter.worldTransform())
                self._paint_erase_stroke(
                    layer_painter, self.current_erase_stroke,
                    self._mark_display_mapper(original_size, scale_x, scale_y, offset_x, offset_y),
                    scale_x)
                layer_painter.end()
            if rubbing is not None:
                # 🧽 An erase brush stroke being drawn: what it has laid so
                # far (screen space, like the view) takes this layer's paint
                # away - on a copy, it is not a mark until the pen lifts.
                image = image.copy()
                layer_painter = QPainter(image)
                layer_painter.setCompositionMode(QPainter.CompositionMode_DestinationOut)
                layer_painter.setOpacity(getattr(self, '_live_ink_alpha', 1.0))   # the pen's transparency
                layer_painter.drawImage(0, 0, rubbing)
                layer_painter.end()
            if layer.impasto and not erasing and rubbing is None:
                # ⛰ Lit as relief (cached; erasing shows it flat until done).
                image = self._impasto_layer(layer, image, view, painter.worldTransform())
            painter.save()
            painter.resetTransform()
            painter.setOpacity(layer.opacity / 100)
            # With the picture hidden there is only the flat background to blend
            # with, and a black one would swallow a Multiply layer whole.
            if self.image_visible or blend:
                painter.setCompositionMode(BLEND_MODES[layer.blend])
            painter.drawImage(0, 0, image)
            painter.restore()

    _prelit = None          # cacheKeys of images already lit (moved lit images, see _layer_image)

    def _impasto_scale(self, view, world=None):
        """Device px per picture px for *view* (and a painter's own transform)."""
        tf = self._layer_view_transform(view)
        if world is not None:
            tf = tf * world
        return math.sqrt(abs(tf.determinant())) or 1.0

    def _impasto_layer(self, layer, image, view, world=None):
        """⛰ *layer*'s image lit as impasto. Kept per layer: lit again only
        when its paint, its settings or the zoom change (on the GPU ~50 ms
        for a full screen, the CPU several times that) - not every frame."""
        from random_image_viewer.drawing import impasto
        prelit = self._prelit or set()
        if image.cacheKey() in prelit:
            return image                    # already lit (moved while zooming)
        scale = self._impasto_scale(view, world)
        key = (image.cacheKey(), image.width(), image.height(),
               impasto.settings_key(layer.impasto), round(scale, 4))
        kept = layer.impasto_lit
        if kept is not None and kept[0] == key:
            return kept[1]
        if not getattr(self, '_impasto_gpu_set', False):
            self._impasto_gpu_set = True
            gpu = getattr(self, 'gpu_processor', None)
            try:
                if gpu is not None and gpu.is_available():
                    impasto.use_gpu(gpu)
            except Exception as e:
                print(f"⛰ Impasto: no GPU ({e}), on the CPU")
        lit = impasto.light(image, layer.impasto, scale)
        layer.impasto_lit = (key, lit, image)
        return lit

    def set_layer_impasto(self, settings):
        """⛰ Impasto on the selected layer: its settings, or None (flat)."""
        self.active_layer.impasto = dict(settings) if settings else None
        self._update_layer_badge()
        self._layer_redraw_timer.start()     # a slider drag: at most one per 30 ms

    def _under_sheet_layer(self):
        """The canvas under the picture as a sheet to paint (layer-like:
        a fill, effects on), or None while it does not show - none set, or
        the picture is shown over it."""
        if (getattr(self, 'under_canvas', None) is None or self.image_visible
                or not self.under_canvas_visible):
            return None
        sheet = self._under_sheet
        sheet.fill = self.under_canvas
        return sheet

    def set_under_canvas(self, on):
        """📄 Canvas's tick in 📚: show or hide the sheet under the picture
        (made by new sketch). It shows while the picture is hidden."""
        self.under_canvas_visible = bool(on)
        self._refresh_layer_window()
        self.enhancement_cache.clear()
        self.scaled_cache.clear()
        if self.current_image:
            self.display_image(self.current_image)
        if on and self.image_visible:
            self.status.showMessage("Canvas under the picture - untick 🖼 Picture to draw on it", 4000)

    def _paint_layer_fill(self, painter, layer, view):
        """A canvas layer's paper: its colour over the whole picture, as the
        picture lies in *view* (turned, flipped, zoomed) - not past its edges."""
        from PySide6.QtGui import QPolygonF
        _w, _h, original_size, scale_x, scale_y, offset_x, offset_y = view
        if self.rotation_angle in (90, 270):
            unrot_w, unrot_h = original_size.height(), original_size.width()
        else:
            unrot_w, unrot_h = original_size.width(), original_size.height()
        to_display = self._mark_display_mapper(original_size, scale_x, scale_y, offset_x, offset_y)
        sheet = self._picture_to_display(to_display, unrot_w, unrot_h).map(
            QPolygonF(QRectF(0, 0, unrot_w, unrot_h)))
        painter.save()
        painter.setPen(Qt.NoPen)
        painter.setBrush(layer.fill)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.drawPolygon(sheet)
        painter.restore()

    def _layer_view_transform(self, view):
        """Picture -> device for *view* (a _paint_marks view tuple)."""
        _w, _h, original_size, scale_x, scale_y, offset_x, offset_y = view
        if self.rotation_angle in (90, 270):
            unrot_w, unrot_h = original_size.height(), original_size.width()
        else:
            unrot_w, unrot_h = original_size.width(), original_size.height()
        return self._picture_to_display(
            self._mark_display_mapper(original_size, scale_x, scale_y, offset_x, offset_y),
            unrot_w, unrot_h)

    def _update_zoom_readout(self):
        """The status bar's zoom: the picture as shown, in % of its real size."""
        label = getattr(self, 'zoom_label', None)
        if label is None:
            return
        per = self._real_pixel_scale()
        if per is None:
            label.setText("")
            return
        percent = per * self.image_label.zoom_factor * 100
        label.setText(f"{percent:.0f}%" if percent >= 10 else f"{percent:.1f}%")

    def _real_pixel_scale(self):
        """Physical screen pixels per pixel of the file, at zoom 1 (fitted):
        what the zoom readout shows, and what 1:1 (⟲) undoes. None without
        a picture."""
        pic = getattr(self, 'original_pixmap', None)
        if pic is None or pic.isNull() or not self.current_image:
            return None
        fitted = pic.size().scaled(self.image_label.size(), Qt.KeepAspectRatio)
        per = fitted.width() / max(1, pic.width())
        # Large pictures are held smaller than the file: count against the
        # file's own size, read from its header once.
        kept = getattr(self, '_real_size', None)
        if kept is None or kept[0] != self.current_image:
            from PySide6.QtGui import QImageReader
            real = QImageReader(self.current_image).size()
            kept = self._real_size = (self.current_image, real if real.isValid() else None)
        real = kept[1]
        if real is not None and min(real.width(), real.height()) > 0:
            if getattr(self, 'studio_mode', False):
                # ◧ The sheet is the canvas and the picture side by side:
                # as tall as the picture, twice as wide.
                held = min(pic.width(), pic.height())
                per *= held / min(real.width(), real.height())
            else:
                per *= max(pic.width(), pic.height()) / max(real.width(), real.height())
        # On a scaled display (Windows at 150 % ...) a window pixel is more
        # than one pixel of the screen: 100 % is one picture pixel per screen pixel.
        try:
            per *= self.image_label.devicePixelRatioF()
        except Exception:
            pass
        return per

    @staticmethod
    def _marks_follow_pen(marks):
        """True when any of *marks* ((kind, mark) pairs) has no colour or
        size of its own and is painted with the pen's current ones (bare
        numbers and dicts from older code)."""
        for kind, mark in marks:
            if kind in ('line', 'hline', 'free_stroke'):
                if not (getattr(mark, 'color', None) and getattr(mark, 'thickness', None)):
                    return True
            elif kind in ('free_line', 'fill'):
                if not isinstance(mark, dict) or 'color' not in mark:
                    return True
                # A width only where there is a line: a filled shape (or a
                # 🌈 gradient) has none - counted as following the pen, a
                # single fill put the pen's colour and size into the layer's
                # key, and every colour change laid the whole layer again
                # (the "loading" every few strokes in a big painting).
                if (kind == 'free_line' or mark.get('shape') == 'polyline') and not mark.get('thickness'):
                    return True
        return False

    def _layer_raster_key(self, width, height, view, count, marks=None):
        """(key, fixed) of a layer's image: everything it depends on, and
        the part of it that a zoom / pan / turn leaves alone.

        The pen's colour and size are in it only when a mark is painted with
        them (*marks*: the layer's (kind, mark) pairs; None: assume so) -
        every stroke carries its own, so changing the brush size or colour
        used to lay the whole drawing again at the next redraw (~1 s with a
        few dozen textured strokes) for the very same pixels."""
        pen = ((self.line_color.rgba(), self.line_thickness)
               if marks is None or self._marks_follow_pen(marks) else ())
        key = (width, height, view[0], view[1], view[2].width(), view[2].height(), *view[3:],
               self.rotation_angle, self.flipped_h, self.flipped_v,
               *pen, self.line_antialiasing, self.pen_pressure_enabled, self.guides_visible)
        # A zoom, pan, quarter turn, flip or resize only moves the pixels:
        # view_tf carries all of them (see _layer_image).
        fixed = (*pen, self.line_antialiasing, self.pen_pressure_enabled, self.guides_visible, count)
        return key, fixed

    _SETTLE_SLICE_S = 0.025     # work per turn of the event loop while settling
    _BUSY_AFTER_S = 0.15        # settling longer than this shows the busy line

    def _settle_view(self):
        """The view has stopped moving: lay the marks properly for it - a
        slice at a time, between which the app keeps answering (the moved and
        scaled images stay on screen meanwhile). Laid in one go, a few dozen
        textured strokes froze it for most of a second after every zoom."""
        self._settle_job = job = object()
        started = time.perf_counter()
        wanted = dict(self._settle_wanted)
        self._settle_wanted.clear()
        work = []
        for layer in self.layers:
            got = wanted.get(id(layer))
            if got is None or not layer.visible or not layer.has_content():
                continue
            width, height, view = got
            marks = list(self._ordered_marks(layer))
            image = QImage(width, height, QImage.Format_ARGB32_Premultiplied)
            image.fill(Qt.transparent)
            if layer.fill is not None:
                paper = QPainter(image)
                self._paint_layer_fill(paper, layer, view)
                paper.end()
            work.append([layer, image, marks, 0, width, height, view])
        total = sum(len(item[2]) for item in work) or 1
        busy = getattr(self, '_busy_line', None)

        def finish():
            self._settle_job = None             # done: nothing under way any more
            for layer, image, marks, _done, width, height, view in work:
                key, fixed = self._layer_raster_key(width, height, view, len(marks), marks)
                layer.raster = {'key': key, 'image': image, 'count': len(marks),
                                'last': marks[-1][1] if marks else None,
                                'fixed': fixed, 'view_tf': self._layer_view_transform(view)}
            self._view_in_motion = False
            if busy is not None and busy.isVisible():
                busy.show_progress(1.0)
            if self.current_image:
                self._smart_zoom_display(settled=True)
            self._hide_gpu_view()           # the plain canvas is there now, for this view
            if busy is not None:
                busy.hide()

        def step():
            if self._settle_job is not job:
                return                          # moved again: a new settle follows
            start = time.perf_counter()
            for item in work:
                layer, image, marks, done, width, height, view = item
                while done < len(marks):
                    if self._keeps_step_at(done, len(marks)):
                        # Kept for undo: the next few undos are a copy.
                        self._keep_raster_step(
                            layer, self._layer_raster_key(width, height, view, len(marks), marks)[0],
                            marks, done, image)
                    painter = QPainter(image)
                    self._paint_layer_marks(painter, marks[done:done + 1], *view)
                    painter.end()
                    done += 1
                    item[3] = done
                    if time.perf_counter() - start > self._SETTLE_SLICE_S:
                        # Taking a while: the line at the bottom of the status
                        # bar says so, and how far it got.
                        if busy is not None and time.perf_counter() - started > self._BUSY_AFTER_S:
                            busy.show_progress(sum(i[3] for i in work) / total)
                        QTimer.singleShot(0, step)
                        return
            finish()

        step()

    # -- 🖼 each layer as one image at the picture's resolution -------------
    #
    # As in a paint program (HeavyPaint ...): a layer's paint is kept as one
    # image in picture coordinates, a little finer than the picture, and every
    # mark goes into it once, when it is made. A zoom, pan, turn or flip only
    # draws that image differently - instant, whole, nothing to wait for. (Laid
    # again for every view instead, a few hundred strokes took a second or more
    # after each zoom, the edges came in late and painting had to wait.)
    # Guides - ruler lines, free lines, polylines - stay lines on the screen,
    # drawn over it as they always were, so they keep their width at any zoom.

    _CANVAS_MAX_SCALE = 1.25            # layer pixels per picture pixel, at most ...
    _CANVAS_MAX_SIDE = 6144             # ... and its longest side ...
    _CANVAS_MAX_PIXELS = 30_000_000     # ... and its size
    _canvas_k = None                    # laying into a layer image: its pixels per picture pixel
    _canvas_fit = 1.0                   # ... and the fitted view's scale (old pen widths)

    def _sheet_unrotated(self):
        """(w, h) of the picture (◧ the sheet) as marks are stored, unturned."""
        pic = self.original_pixmap
        if self.rotation_angle in (90, 270):
            return pic.height(), pic.width()
        return pic.width(), pic.height()

    def _canvas_geometry(self, marks, room=False):
        """(QRect in picture coords, scale) of a layer image holding *marks*:
        the picture, and whatever is painted past its edges."""
        from random_image_viewer.drawing import transform as mark_transform
        uw, uh = self._sheet_unrotated()
        area = QRectF(0, 0, uw, uh)
        drawn = self._paint_bounds(marks)
        if not drawn.isEmpty():
            area = area.united(drawn.adjusted(-4, -4, 4, 4))
        rect = area.toAlignedRect()
        k = self._canvas_scale_for(rect)
        if room:
            # Growing: room around it, so the next strokes past the edge
            # fit too - but never so much that it would be coarser.
            pad = int(max(128, 0.12 * max(uw, uh)))
            while pad >= 32:
                padded = rect.adjusted(-pad, -pad, pad, pad)
                if self._canvas_scale_for(padded) >= k - 1e-9:
                    return padded, k
                pad //= 2
        return rect, k

    _CANVAS_REACH = 0.25        # a spray cloud grows a layer image this share of the sheet past each edge

    def _canvas_reach(self):
        """How far past the sheet a spray stroke's cloud grows a layer image."""
        uw, uh = self._sheet_unrotated()
        m = self._CANVAS_REACH * max(uw, uh)
        return QRectF(-m, -m, uw + 2 * m, uh + 2 * m)

    def _paint_bounds(self, marks):
        """What a layer image must hold of *marks* (picture coords): all of
        their paint, wherever it is - but a 🌫 spray stroke only as far as
        _canvas_reach. Its bounds are its whole cloud (thousands of px, mostly
        empty), which grew the image to 5550 x 5406 and, to stay in the size
        limits, made the whole layer coarser (0.69 px per picture px). Limiting
        every mark the same cut off paint painted far past the sheet (a hard
        edge, other layers going on past it)."""
        spray, other = [], []
        for kind, mark in marks:
            texture = str(getattr(mark, 'texture', '') or '') if kind == 'free_stroke' else ''
            (spray if texture.startswith(brushes.SPRAY) else other).append((kind, mark))
        area = mark_transform.bounds(other) if other else QRectF()
        if spray:
            cloud = mark_transform.bounds(spray).intersected(self._canvas_reach())
            if not cloud.isEmpty():
                area = cloud if area.isEmpty() else area.united(cloud)
        return area

    def _canvas_scale_for(self, rect):
        w, h = max(1.0, rect.width()), max(1.0, rect.height())
        k = min(self._canvas_top_scale(), self._CANVAS_MAX_SIDE / max(w, h),
                math.sqrt(self._CANVAS_MAX_PIXELS / (w * h)))
        return max(0.05, k)

    _CANVAS_TOP_SCALE = 4.0     # layer pixels per picture pixel, never more

    def _canvas_top_scale(self):
        """The finest a layer image is made: 1.25 picture px - or as fine as
        the screen shows the picture fitted, in its real pixels, where that
        is finer. On a 4K screen at 150 % a sketch is shown ~1.9 screen px
        per picture px: at 1.25 the paint was stretched 1.5x on its way to
        the screen - the soft look next to HeavyPaint. Now one paint pixel
        lands on one screen pixel at fit (the size limits still apply)."""
        top = self._CANVAS_MAX_SCALE
        try:
            dpr = self.image_label.devicePixelRatioF()
            top = max(top, self._fitted_scale() * dpr)
        except Exception:
            pass
        return min(self._CANVAS_TOP_SCALE, top)

    def _grown_canvas(self, layer, kept, need, k):
        """*kept* (a layer image) moved whole into a bigger one holding the
        picture area *need*, at the same scale *k*: a copy, not every mark
        laid again (seconds with a few hundred strokes, at every stroke past
        the edge). Its undo patches move with it. (image, rect) or None
        where the scale is not the same."""
        if abs(k - kept['k']) > 1e-9:
            return None
        old = QRectF(kept['rect'])
        need = QRectF(need).united(old)
        # Whole pixels of offset, so the old image is copied, not resampled -
        # an even number: the thickness map (half the size) moves whole
        # pixels too, and is copied the same way (see _update_height).
        step = max(1, round(1.0 / self._HEIGHT_SCALE))
        dx = step * max(0, math.ceil(((old.x() - need.x()) * k - 1e-6) / step))
        dy = step * max(0, math.ceil(((old.y() - need.y()) * k - 1e-6) / step))
        x, y = old.x() - dx / k, old.y() - dy / k
        rect = QRectF(x, y, need.right() - x, need.bottom() - y)
        w, h = self._canvas_view(rect, k)[:2]
        image = QImage(w, h, QImage.Format_ARGB32_Premultiplied)
        image.fill(Qt.transparent)
        painter = QPainter(image)
        painter.setCompositionMode(QPainter.CompositionMode_Source)
        painter.drawImage(dx, dy, kept['image'])
        painter.end()
        for patch in getattr(layer, 'canvas_patches', None) or []:
            patch['box'] = patch['box'].translated(dx, dy)
        return image, rect

    def _canvas_view(self, rect, k):
        """The _paint_marks view tuple that lays picture coords into a layer
        image of *rect* at *k* (turns and flips off while laying)."""
        uw, uh = self._sheet_unrotated()
        return (max(1, math.ceil(rect.width() * k)), max(1, math.ceil(rect.height() * k)),
                QSize(uw, uh), k, k, -rect.x() * k, -rect.y() * k)

    def _laying_canvas(self, k):
        """Context: marks laid into a layer image - unturned, unflipped, pen
        widths in picture pixels (see _paint_layer_marks)."""
        from contextlib import contextmanager

        @contextmanager
        def ctx():
            saved = (self.rotation_angle, self.flipped_h, self.flipped_v, self._canvas_k, self._canvas_fit)
            fit = self._fitted_scale()
            self.rotation_angle, self.flipped_h, self.flipped_v = 0, False, False
            self._canvas_k, self._canvas_fit = k, fit
            try:
                yield
            finally:
                (self.rotation_angle, self.flipped_h, self.flipped_v,
                 self._canvas_k, self._canvas_fit) = saved
        return ctx()

    def _fitted_scale(self):
        """Screen pixels per picture pixel with the picture fitted (zoom 1)."""
        try:
            pic = self.original_pixmap
            fitted = pic.size().scaled(self.image_label.size(), Qt.KeepAspectRatio)
            return max(1e-3, fitted.width() / max(1, pic.width()))
        except Exception:
            return 1.0

    def _view_scale(self):
        """Screen pixels per picture pixel now."""
        try:
            return max(1e-3, self._fx_view_params()[1])
        except Exception:
            return 1.0

    def _layer_canvas(self, layer, marks):
        """*layer*'s paint (*marks*, guides left out) as its image in picture
        coordinates: (image, rect, k). Kept; new marks go onto it, undo takes
        a kept step or lays it again (see _lay_marks)."""
        hidden = self._sel_hidden
        if hidden:
            marks = [(kind, m) for kind, m in marks if id(m) not in hidden]
        pen = ((self.line_color.rgba(), self.line_thickness)
               if self._marks_follow_pen(marks) else ())
        kept = layer.raster if (layer.raster or {}).get('canvas') else None
        if (kept is not None and kept.get('key') == 'adopt' and marks
                and (kept['k'] < 0.9 * self._canvas_geometry(marks)[1]
                     # (or cut short of its paint: saved while layer images
                     # stopped a quarter of the sheet past its edges)
                     or not QRectF(kept['rect']).adjusted(-2, -2, 2, 2).contains(
                         QRectF(self._canvas_geometry(marks)[0])))):
            # 💼 a project's image saved coarser than this screen shows it
            # (made at 1.25 before layer images followed the screen): laid
            # again from its strokes, once, at the finer scale
            kept = layer.raster = None
            layer.canvas_patches = []
        rect, k = (kept['rect'], kept['k']) if kept is not None else self._canvas_geometry(marks)
        uw, uh = self._sheet_unrotated()

        def key_for(rect, k):
            return ('canvas', uw, uh, rect.x(), rect.y(), rect.width(), rect.height(), round(k, 5),
                    *pen, self.line_antialiasing, self.pen_pressure_enabled,
                    frozenset(hidden) if hidden else None,
                    layer.fill.rgba() if layer.fill is not None else None)

        if kept is not None and kept.get('key') == 'adopt':
            # \U0001F4BC opened from a project: the image saved with it, as
            # this view's own (its undo patches with it)
            kept['key'] = key_for(rect, k)
            for patch in getattr(layer, 'canvas_patches', None) or []:
                if patch.get('key') == 'adopt':
                    patch['key'] = kept['key']
        if kept is not None and len(marks) > kept['count']:
            # Something new past the image's edge: a bigger image - the one
            # there moved into it when nothing else changed (see _grown_canvas).
            from random_image_viewer.drawing import transform as mark_transform
            new = self._paint_bounds(marks[kept['count']:])
            if not new.isEmpty() and not QRectF(rect).contains(new):
                need, k = self._canvas_geometry(marks, room=True)
                rect = need
                if (kept['key'] == key_for(kept['rect'], kept['k']) and layer.fill is None
                        and (not kept['count'] or marks[kept['count'] - 1][1] is kept['last'])):
                    grown = self._grown_canvas(layer, kept, need, k)
                    if grown is not None:
                        image, rect = grown
                        new_key = key_for(rect, k)
                        for patch in getattr(layer, 'canvas_patches', None) or []:
                            if patch['key'] == kept['key']:
                                patch['key'] = new_key
                        kept = dict(kept, image=image, rect=rect, key=new_key)
                        layer.raster = kept
        key = key_for(rect, k)
        view = self._canvas_view(rect, k)
        key_before = kept['image'].cacheKey() if kept is not None else None
        self.__dict__.pop('_undo_boxes', None)
        if (kept is not None and kept['key'] == key and len(marks) < kept['count']
                and self._undo_patches(layer, kept, marks)):
            # Undo: the patches the last marks covered, put back - not the
            # whole image laid again (2 s with a few hundred strokes).
            image, done = kept['image'], len(marks)
        elif (kept is not None and kept['key'] == key and kept['count'] <= len(marks)
                and (not kept['count'] or marks[kept['count'] - 1][1] is kept['last'])):
            image, done = kept['image'], kept['count']
            if done < len(marks):
                self._keep_patch(layer, key, kept, marks, done, rect, k, image)
        else:
            layer.canvas_patches = []
            step = self._raster_step_for(layer, key, marks)
            if step is not None:
                image, done = step['image'].copy(), step['count']
            else:
                image = QImage(view[0], view[1], QImage.Format_ARGB32_Premultiplied)
                image.fill(Qt.transparent)
                done = 0
                if layer.fill is not None:
                    with self._laying_canvas(k):
                        paper = QPainter(image)
                        self._paint_layer_fill(paper, layer, view)
                        paper.end()
        laid_from = done
        if done < len(marks):
            self.__dict__.pop('_refine_wanted', None)
            with self._laying_canvas(k):
                self._lay_marks(layer, image, marks, done, view, key)
        if kept is not None and image is kept['image']:
            # 🎮 Where it changed, for its texture on the graphics card.
            rects = list(self.__dict__.pop('_undo_boxes', None) or [])
            if laid_from < len(marks):
                rects.append(self._marks_canvas_box(marks[laid_from:], rect, k, image))
            self._canvas_note(image, rects, key_before)
        layer.raster = {'canvas': True, 'key': key, 'image': image, 'count': len(marks),
                        'last': marks[-1][1] if marks else None, 'rect': rect, 'k': k}
        if layer.impasto:
            self._update_height(layer, marks, rect, k, key, image)      # ⛰ its thickness, alongside
        self._queue_refines(layer, key)
        return image, rect, k

    # -- 🔥 a stroke burnt in as drawn ------------------------------------
    #
    # A stroke just drawn is on screen already, every stamp laid. When the
    # pen lifts that picture goes into the layer's image (one drawImage) -
    # laying its stamps again there took seconds after a long scribble
    # (~8000 stamps: 3.4 s), every time. Where the screen was coarser than
    # the layer's image (zoomed out, turned), the stroke is laid again
    # exactly in the background, a few ms at a time while nothing else
    # happens, and put in place of the burnt one - unless something was
    # painted after it meanwhile (then the burnt one stays).

    _REFINE_SLICE_S = 0.008     # background work per turn of the event loop
    _REFINE_CHUNK = 12          # stamps per step

    def _burn_render(self, painter, mark, render, view):
        """Lay *mark* into a layer image from its live render (screen
        pixels) through *view*. False when it cannot."""
        inv, ok = render[0].inverted()
        if not ok:
            return False
        burn = inv * view
        painter.save()
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.setTransform(burn, True)
        painter.drawImage(QPointF(render[2]), render[1])
        painter.restore()
        mark.render = None          # it is in the layer now: its screen picture not needed
        scale_render = math.sqrt(abs(render[0].determinant()))
        scale_view = math.sqrt(abs(view.determinant()))
        exact = (abs(burn.m12()) < 1e-6 and abs(burn.m21()) < 1e-6
                 and scale_render >= scale_view * 0.98)
        if not exact and mark.stamps and getattr(mark, 'history', None) is None:
            self.__dict__.setdefault('_refine_wanted', []).append((mark, QTransform(view)))
        return True

    def _queue_refines(self, layer, key):
        """The strokes just burnt coarser than the layer: to lay again exactly.
        Off: the stroke laid again came out different (a hard grey rim round
        soft strokes, ~2 s after drawing them) and the work in the background
        competed with the pen. The burnt stroke - as it was seen while drawn -
        stays."""
        wanted = self.__dict__.pop('_refine_wanted', None)
        if not wanted or not self.__dict__.get('_refine_on', False):
            return
        jobs = [j for j in getattr(self, '_refine_jobs', []) if j['layer'] is not layer]
        mark, view = wanted[-1]     # only the newest can be put back (see _refine_valid)
        jobs.append({'layer': layer, 'mark': mark, 'key': key, 'view': view, 'work': None, 'done': 0})
        self._refine_jobs = jobs
        timer = getattr(self, '_refine_timer', None)
        if timer is None:
            timer = self._refine_timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(self._refine_tick)
        timer.start(150)

    def _refine_valid(self, job):
        """Its layer image unchanged since: the stroke still the last thing
        in it, its undo patch (the image before it) there."""
        kept = job['layer'].raster
        if not kept or not kept.get('canvas') or kept['key'] != job['key'] or kept['last'] is not job['mark']:
            return None
        patches = getattr(job['layer'], 'canvas_patches', None) or []
        if not patches:
            return None
        patch = patches[-1]
        if patch['key'] != job['key'] or patch['count'] != kept['count'] - 1:
            return None
        return kept, patch

    def _refine_tick(self):
        jobs = getattr(self, '_refine_jobs', None)
        if not jobs:
            return
        timer = self._refine_timer
        if (getattr(self, 'is_drawing_free_stroke', False) or getattr(self, '_view_in_motion', False)
                or getattr(self, '_settle_job', None) is not None):
            timer.start(120)        # not while painting or zooming
            return
        job = jobs[0]
        valid = self._refine_valid(job)
        if valid is None:
            jobs.pop(0)
            if jobs:
                timer.start(0)
            return
        kept, patch = valid
        mark, view = job['mark'], job['view']
        try:
            if job['work'] is None:
                texture = brushes.load_texture(mark.texture)
                if texture is None or getattr(texture, 'procedural', False):
                    jobs.pop(0)
                    return
                scale = math.sqrt(abs(view.determinant()))
                box = brushes._stamps_box(mark.stamps, view, scale).intersected(patch['box'])
                if box.isEmpty():
                    jobs.pop(0)
                    return
                if mark.flat:
                    work = brushes.flat_stroke(texture, box, None)
                else:
                    work = QImage(box.size(), QImage.Format_ARGB32_Premultiplied)
                    work.fill(Qt.transparent)
                job.update(work=work, box=box, texture=texture, image=kept['image'])
            if kept['image'] is not job['image']:
                jobs.pop(0)
                return
            stamps, box, work = mark.stamps, job['box'], job['work']
            started = time.perf_counter()
            while job['done'] < len(stamps) and time.perf_counter() - started < self._REFINE_SLICE_S:
                chunk = stamps[job['done']:job['done'] + self._REFINE_CHUNK]
                if mark.flat:
                    work.add(job['texture'], chunk, view)
                else:
                    p = QPainter(work)
                    p.translate(-box.x(), -box.y())
                    brushes.paint_stamps(p, job['texture'], chunk, view)
                    p.end()
                job['done'] += len(chunk)
            if job['done'] < len(stamps):
                timer.start(0)
                return
            # Laid exactly: the image before the stroke back, the stroke on it.
            stroke = work.compose(box) if mark.flat else work
            before = kept['image'].cacheKey()
            p = QPainter(kept['image'])
            p.setClipRect(patch['box'])
            p.setCompositionMode(QPainter.CompositionMode_Source)
            p.drawImage(patch['box'].topLeft(), patch['image'])
            p.setCompositionMode(QPainter.CompositionMode_SourceOver)
            p.drawImage(box.topLeft(), stroke)
            p.end()
            self._canvas_note(kept['image'], [QRect(patch['box'])], before)
            jobs.pop(0)
            if self.current_image:
                self.display_image(self.current_image)
        except Exception as e:
            print(f"🔥 Stroke refine skipped: {e}")
            jobs.pop(0)
        if jobs:
            timer.start(0)

    _PATCHES_KEPT = 80                  # undo patches per layer ...
    _PATCHES_BYTES = 400 << 20          # ... and at most this much memory for all layers

    def _keep_patch(self, layer, key, kept, marks, done, rect, k, image):
        """Before marks[done:] go onto *image*: the part of it they will
        cover, kept, so undo puts that back (as a paint program does)."""
        box = self._marks_canvas_box(marks[done:], rect, k, image)
        if box.isEmpty():
            return
        patches = getattr(layer, 'canvas_patches', None) or []
        patches.append({'key': key, 'count': done, 'last': marks[done - 1][1] if done else None,
                        'box': box, 'image': image.copy(box)})
        patches = patches[-self._PATCHES_KEPT:]
        layer.canvas_patches = patches
        total = sum(p['image'].sizeInBytes() for l in self.layers
                    for p in (getattr(l, 'canvas_patches', None) or []))
        while total > self._PATCHES_BYTES and patches:
            total -= patches.pop(0)['image'].sizeInBytes()      # the oldest go first

    def _marks_canvas_box(self, marks, rect, k, image):
        """The part of a layer image (*rect*, *k*) that *marks* paint into,
        with room for every stroke's width there: a round pen's width is
        kept in picture px (pic_width), wider than its screen thickness
        when drawn zoomed out - a box from the screen width left its edge
        out (undo left a rim; the graphics card's copy missed it)."""
        from random_image_viewer.drawing import transform as mark_transform
        area = mark_transform.bounds(marks)
        if area.isEmpty():
            return QRect()
        extra = 0.0
        for kind, mark in marks:
            if kind == 'free_stroke' and not getattr(mark, 'stamps', None):
                width = getattr(mark, 'pic_width', None) or getattr(mark, 'thickness', None) or 1
                extra = max(extra, width * 0.75)
            elif isinstance(mark, dict) and kind in ('free_line', 'fill') and (
                    kind == 'free_line' or mark.get('shape') == 'polyline'):
                width = (mark.get('pic_width') or (mark.get('thickness') or 1) / self._canvas_fit)
                extra = max(extra, width * 0.75)
        area = area.adjusted(-extra, -extra, extra, extra)
        box = QRectF((area.x() - rect.x()) * k, (area.y() - rect.y()) * k,
                     area.width() * k, area.height() * k).toAlignedRect().adjusted(-4, -4, 4, 4)
        return box.intersected(image.rect())

    def _canvas_note(self, image, rects, before):
        """🎮 *image* (a layer's own) changed in *rects* since cacheKey
        *before*: its texture on the graphics card gets just those (see
        GpuView._layer_texture). A change not noted breaks the chain of
        keys, and the whole image goes up again - never a stale copy."""
        # One record per GPU window (the canvas, the zoom window): each keeps
        # its own copy of the image. Shared, the zoom window (zooming with a
        # shape or gradient tool on) took the changes up into its copy and
        # marked them done - the canvas's copy stayed without them: gradients
        # gone on going back to the brush, back a stroke's box at a time.
        for notes in (self.__dict__.get('_canvas_notes') or {}).values():
            entry = notes.get(image.cacheKey() >> 32)
            if entry is None:
                continue            # not on that card yet: it goes up whole
            if entry.get('key') != before:
                entry['all'] = True
            else:
                entry['rects'] = list(entry.get('rects') or []) + [QRect(r) for r in rects if not r.isEmpty()]
                if len(entry['rects']) > 64:
                    entry['all'] = True
            entry['key'] = image.cacheKey()

    def _undo_patches(self, layer, kept, marks):
        """*layer*'s image back to *marks* (fewer than it holds) by putting
        back the patches kept before the ones gone. False when they are not
        all there (then it is laid again)."""
        patches = getattr(layer, 'canvas_patches', None) or []
        want = len(marks)
        need = []
        for p in reversed(patches):
            if p['key'] != kept['key'] or p['count'] < want:
                break
            need.append(p)
            if p['count'] == want:
                break
        if not need or need[-1]['count'] != want or (
                want and marks[want - 1][1] is not need[-1]['last']):
            return False
        painter = QPainter(kept['image'])
        painter.setCompositionMode(QPainter.CompositionMode_Source)
        for p in need:                      # newest first, back to *want*
            painter.drawImage(p['box'].topLeft(), p['image'])
        painter.end()
        self._undo_boxes = [QRect(p['box']) for p in need]
        layer.canvas_patches = patches[:len(patches) - len(need)]
        return True

    # -- ⛰ impasto: the paint's real thickness ----------------------------
    #
    # Beside an impasto layer's colour image, a thickness map of the same
    # size (16-bit, its alpha the thickness), laid from the same marks: a
    # textured stroke again with its own tip, white, each stamp's opacity
    # the paint's thickness there - thick where the stroke starts, thinning
    # as the brush runs dry - so the hairs' gaps are real grooves; other
    # marks (shapes, lines, the round pen, baked strokes) a thin coat of
    # their coverage; erasing takes thickness away. Coats build up (over).
    # Laid on as the colour is (new marks only); anything else - undo, a
    # change of the image - lays it all again. impasto.light_height lights
    # it, only where it changed.

    _HEIGHT_STROKE = 0.62       # a textured stroke's thickness where it starts
    _HEIGHT_DRY = 0.45          # ... this much thinner where it ends (the brush running dry)
    _HEIGHT_COAT = 0.30         # shapes, lines, the round pen: a thin coat
    _HEIGHT_LEVEL = 0.65        # a stroke wipes this much of the relief under it first

    def _height_stamps(self, stamps):
        n = len(stamps)
        out = []
        for i, s in enumerate(stamps):
            load = 1.0 - self._HEIGHT_DRY * (i / max(1, n - 1)) ** 1.2
            out.append((s[0], s[1], s[2], s[3], s[4] * self._HEIGHT_STROKE * load, 0xFFFFFF) + tuple(s[6:]))
        return out

    def _paint_height_marks(self, painter, marks, view):
        """Lay *marks*' thickness onto *painter* (a thickness map, see above)."""
        canvas_width, canvas_height, original_size, sx, sy, ox, oy = view
        to_display = self._mark_display_mapper(original_size, sx, sy, ox, oy)
        uw, uh = self._sheet_unrotated()
        tview = self._picture_to_display(to_display, uw, uh)
        from random_image_viewer.drawing import transform as mark_transform
        with self._busy_progress("⛰ Impasto: building the relief", len(marks)) as tick:
            self._paint_height_each(painter, marks, view, tview, mark_transform, tick)

    def _paint_height_each(self, painter, marks, view, tview, mark_transform, tick):
        canvas_width, canvas_height = view[0], view[1]
        for i, (kind, mark) in enumerate(marks):
            tick(i)
            if self._is_guide(kind, mark):
                continue
            if kind == 'erase' or (kind == 'free_stroke' and getattr(mark, 'erase', False)):
                self._paint_layer_marks(painter, [(kind, mark)], *view)      # takes thickness away too
                continue
            if (kind == 'free_stroke' and getattr(mark, 'stamps', None) and not getattr(mark, 'clip', None)
                    and getattr(mark, 'history', None) is None):
                texture = brushes.load_texture(mark.texture)
                if texture is not None:
                    # new paint levels what is under it: where it covers, most
                    # of the old relief goes first (laid only over, the grooves
                    # of every stroke beneath showed through at full depth)
                    level = [(s[0], s[1], s[2], s[3], s[4] * self._HEIGHT_LEVEL, 0xFFFFFF) + tuple(s[6:])
                             for s in mark.stamps]
                    painter.save()
                    painter.setCompositionMode(QPainter.CompositionMode_DestinationOut)
                    brushes.paint_stamps(painter, texture, level, tview, (canvas_width, canvas_height),
                                         flat=getattr(mark, 'flat', False))
                    painter.restore()
                    brushes.paint_stamps(painter, texture, self._height_stamps(mark.stamps), tview,
                                         (canvas_width, canvas_height), flat=getattr(mark, 'flat', False))
                    continue
            # anything else: its coverage, as a thin coat
            b = mark_transform.bounds([(kind, mark)])
            if b.isEmpty():
                continue
            width = 0.0
            if isinstance(mark, dict):
                width = float(mark.get('pic_width') or mark.get('thickness') or 0)
            else:
                width = float(getattr(mark, 'pic_width', None) or getattr(mark, 'thickness', 0) or 0)
            b = b.adjusted(-width, -width, width, width)
            box = tview.mapRect(b).toAlignedRect().adjusted(-4, -4, 4, 4).intersected(
                QRect(0, 0, canvas_width, canvas_height))
            if box.isEmpty():
                continue
            scratch = QImage(box.size(), QImage.Format_ARGB32_Premultiplied)
            scratch.fill(Qt.transparent)
            sp = QPainter(scratch)
            sp.translate(-box.x(), -box.y())
            self._paint_layer_marks(sp, [(kind, mark)], *view)
            sp.end()
            tint = QPainter(scratch)
            tint.setCompositionMode(QPainter.CompositionMode_SourceIn)
            tint.fillRect(scratch.rect(), QColor(255, 255, 255))
            tint.end()
            painter.save()
            painter.setOpacity(self._HEIGHT_COAT)
            painter.drawImage(box.topLeft(), scratch)
            painter.restore()

    _BUSY_AFTER = 0.25          # s: work longer than this shows its progress
    _BUSY_EVERY = 0.05          # s: the bar drawn at most this often

    @contextlib.contextmanager
    def _busy_progress(self, text, total):
        """A loader for long work on the main thread, e.g. ⛰ impasto laying
        every stroke again: in the middle of the GPU canvas (or, on the
        plain canvas, a bar in the status bar), with the wait cursor.
        Yields tick(i) to call per item; it shows only once the work has
        taken _BUSY_AFTER. Painted at once (GpuCanvasWindow.paint_busy,
        repaint()) - no event loop runs: a redraw coming in would lay the
        same strokes again. (A new window of its own never showed: Windows
        shows it only from the event loop.)"""
        start = time.perf_counter()
        state = {'shown': False, 'drawn': 0.0, 'gpu': None}
        status = getattr(self, 'status', None)

        def tick(i):
            if total < 2:
                return
            now = time.perf_counter()
            if now - start < self._BUSY_AFTER or now - state['drawn'] < self._BUSY_EVERY:
                return
            state['drawn'] = now
            if not state['shown']:
                state['shown'] = True
                QApplication.setOverrideCursor(Qt.WaitCursor)
            gpu = self._gpu_target() if self.__dict__.get('_gpu_display') else None
            if gpu is not None and hasattr(gpu, 'paint_busy') and gpu.isVisible():
                try:
                    if gpu.paint_busy((f"{text}   {i} / {total}", i / total)):
                        state['gpu'] = gpu
                        return
                except Exception as e:
                    print(f"⛰ loader on the canvas failed: {e}")
            if status is None or not status.isVisible():
                return
            bar = self.__dict__.get('_busy_box')
            if bar is None:
                bar = QProgressBar()
                bar.setTextVisible(True)
                bar.setAlignment(Qt.AlignCenter)
                status.insertPermanentWidget(0, bar)
                self._busy_box = bar
            if not bar.isVisible():
                bar.setRange(0, total)
                bar.setFormat(f"{text}  %v / %m")
                # (wide enough for its text: the status bar's message
                # beside it squeezed a label to nothing)
                bar.setFixedWidth(bar.fontMetrics().horizontalAdvance(f"{text}  {total} / {total}") + 40)
                bar.show()
                # laid out now (a posted layout request waits for the event
                # loop, which does not run until the work is done)
                QApplication.sendEvent(status, QEvent(QEvent.LayoutRequest))
                status.layout().activate()
            bar.setValue(i)
            status.repaint()

        try:
            yield tick
        finally:
            if state['shown']:
                QApplication.restoreOverrideCursor()
                bar = self.__dict__.get('_busy_box')
                if bar is not None:
                    bar.hide()
                gpu = state['gpu']
                if gpu is not None:
                    gpu.busy_note = None        # (the frame after the work leaves it out)
                    gpu._full = True
                    gpu.update()

    _HEIGHT_SCALE = 0.5     # the thickness map at this share of the colour's resolution
                            # (a quarter of the pixels: laying it cost more than the pen-up)

    def _update_height(self, layer, marks, rect, k, key, canvas):
        """*layer*'s thickness map brought up to its marks (see above), at
        _HEIGHT_SCALE of the colour image's size."""
        hm = getattr(layer, 'height_map', None)
        n = len(marks)
        serial = canvas.cacheKey() >> 32
        k = k * self._HEIGHT_SCALE
        want = QSize(max(1, math.ceil(rect.width() * k)), max(1, math.ceil(rect.height() * k)))
        if hm is not None and hm['count'] > n and self._height_undo(layer, marks, key, canvas):
            return                          # undo: its patches put back
        box = None
        if (hm is not None and hm['key'] == key and hm['canvas'] == serial
                and hm['image'].size() == want and hm['count'] <= n
                and (hm['count'] == 0 or marks[hm['count'] - 1][1] is hm['last'])):
            if hm['count'] == n:
                return
            done, img = hm['count'], hm['image']
            box = self._marks_canvas_box(marks[done:], rect, k, img)
            # (in the colour image's pixels, for its lighting - the map is smaller)
            up = 1.0 / self._HEIGHT_SCALE
            cbox = QRectF(box.x() * up, box.y() * up, box.width() * up, box.height() * up).toAlignedRect()
            dirty = None if hm.get('dirty') is None else list(hm['dirty']) + ([cbox] if not box.isEmpty() else [])
            patches = list(hm.get('patches') or [])
            if not box.isEmpty():
                # what the new marks cover, kept: undo puts it back (not all laid again)
                patches.append({'count': done, 'last': marks[done - 1][1] if done else None,
                                'box': QRect(box), 'image': img.copy(box)})
                patches = patches[-self._PATCHES_KEPT:]
            packed = hm.get('packed')
        elif (grown := self._grown_height(hm, marks, rect, k, key, want)) is not None:
            # the layer image grew (a stroke past its edge): the map moved
            # into a bigger one, only the new marks laid - all of them laid
            # again took seconds at every stroke past the edge
            img, done, patches = grown
            box = self._marks_canvas_box(marks[done:], rect, k, img)
            dirty, packed = None, None
            if not box.isEmpty():
                patches.append({'count': done, 'last': marks[done - 1][1],
                                'box': QRect(box), 'image': img.copy(box)})
                patches = patches[-self._PATCHES_KEPT:]
        else:
            img = QImage(want, QImage.Format_RGBA64_Premultiplied)
            img.fill(Qt.transparent)
            done, dirty, patches, packed = 0, None, [], None
        view = self._canvas_view(rect, k)
        with self._laying_canvas(k):
            p = QPainter(img)
            p.setRenderHint(QPainter.Antialiasing, True)
            p.setRenderHint(QPainter.SmoothPixmapTransform, True)
            self._paint_height_marks(p, marks[done:], view)
            p.end()
        layer.height_map = {'key': key, 'canvas': serial, 'image': img, 'count': n,
                            'last': marks[-1][1] if marks else None, 'dirty': dirty,
                            'serial': (hm['serial'] + 1) if hm is not None else 1,
                            'patches': patches, 'packed': packed, 'rect': QRectF(rect), 'k': k}
        self._pack_height(layer.height_map, [box] if (box is not None and not box.isEmpty()) else None)

    def _grown_height(self, hm, marks, rect, k, key, want):
        """The thickness map *hm* moved whole into one of size *want* for the
        layer image's bigger *rect* (same marks before, same scale *k*, the
        map's): (image, marks done, patches moved) or None."""
        if (hm is None or hm.get('rect') is None or not hm['count'] or hm['count'] > len(marks)
                or marks[hm['count'] - 1][1] is not hm['last'] or abs(hm['k'] - k) > 1e-9
                or not isinstance(key, tuple) or not isinstance(hm['key'], tuple)
                or len(key) != len(hm['key']) or key[:3] != hm['key'][:3] or key[7:] != hm['key'][7:]):
            return None
        old = hm['rect']
        fx, fy = (old.x() - rect.x()) * k, (old.y() - rect.y()) * k
        dx, dy = round(fx), round(fy)
        if (abs(fx - dx) > 1e-3 or abs(fy - dy) > 1e-3 or dx < 0 or dy < 0
                or dx + hm['image'].width() > want.width() + 1 or dy + hm['image'].height() > want.height() + 1):
            return None             # (not a whole-pixel move into a bigger one: laid again)
        img = QImage(want, QImage.Format_RGBA64_Premultiplied)
        img.fill(Qt.transparent)
        p = QPainter(img)
        p.setCompositionMode(QPainter.CompositionMode_Source)
        p.drawImage(dx, dy, hm['image'])
        p.end()
        patches = [dict(pt, box=pt['box'].translated(dx, dy)) for pt in (hm.get('patches') or [])]
        return img, hm['count'], patches

    def _height_undo(self, layer, marks, key, canvas):
        """The thickness map back to fewer *marks* from its kept patches (as
        the colour's undo). True when it could."""
        hm = getattr(layer, 'height_map', None)
        if hm is None or hm['key'] != key or hm['canvas'] != (canvas.cacheKey() >> 32):
            return False
        want = len(marks)
        patches = hm.get('patches') or []
        need = []
        for pt in reversed(patches):
            if pt['count'] < want:
                break
            need.append(pt)
            if pt['count'] == want:
                break
        if not need or need[-1]['count'] != want or (want and marks[want - 1][1] is not need[-1]['last']):
            return False
        p = QPainter(hm['image'])
        p.setCompositionMode(QPainter.CompositionMode_Source)
        for pt in need:
            p.drawImage(pt['box'].topLeft(), pt['image'])
        p.end()
        hm['patches'] = patches[:len(patches) - len(need)]
        hm['count'] = want
        hm['last'] = marks[want - 1][1] if want else None
        boxes = [QRect(pt['box']) for pt in need]
        if hm.get('dirty') is not None:
            up = 1.0 / self._HEIGHT_SCALE           # (the lighting's boxes: the colour's pixels)
            hm['dirty'] = list(hm['dirty']) + [
                QRectF(b.x() * up, b.y() * up, b.width() * up, b.height() * up).toAlignedRect() for b in boxes]
        hm['serial'] += 1
        self._pack_height(hm, boxes)
        return True

    def _pack_height(self, hm, boxes):
        """🎮 The thickness map for the graphics card: 16 bits as R (high)
        and G (low) of an 8-bit image (the GPU blurs it by its mipmaps; a
        linear mix of the two bytes is the mix of the 16-bit value). Only
        *boxes* (None: all), and their change noted for the texture."""
        import numpy as np
        img = hm['image']
        packed = hm.get('packed')
        if packed is None or packed.size() != img.size():
            packed = QImage(img.size(), QImage.Format_ARGB32_Premultiplied)
            packed.fill(QColor(0, 0, 0, 255))
            boxes = None
        before = packed.cacheKey()
        w, h = img.width(), img.height()
        src_line = img.bytesPerLine() // 2
        src = np.frombuffer(img.constBits(), np.uint16, count=src_line * h).reshape(h, src_line)[:, :w * 4]
        src = src.reshape(h, w, 4)[:, :, 3]
        dst = np.frombuffer(packed.bits(), np.uint8, count=packed.bytesPerLine() * h).reshape(
            h, packed.bytesPerLine())[:, :w * 4].reshape(h, w, 4)
        areas = [QRect(0, 0, w, h)] if boxes is None else [b.intersected(QRect(0, 0, w, h)) for b in boxes]
        for b in areas:
            if b.isEmpty():
                continue
            s = src[b.y():b.bottom() + 1, b.x():b.right() + 1]
            d = dst[b.y():b.bottom() + 1, b.x():b.right() + 1]
            d[:, :, 2] = (s >> 8).astype(np.uint8)      # R: high byte
            d[:, :, 1] = (s & 0xFF).astype(np.uint8)    # G: low byte
            d[:, :, 0] = 0
            d[:, :, 3] = 255
        hm['packed'] = packed
        self._canvas_note(packed, [] if boxes is None else areas, before)
        if boxes is None:
            # a new image, or all of it: its texture goes up whole
            for notes in (self.__dict__.get('_canvas_notes') or {}).values():
                entry = notes.get(packed.cacheKey() >> 32)
                if entry is not None:
                    entry['all'] = True

    def _impasto_uniforms(self, settings, k):
        """The impasto shader's settings (see GpuView._IMPASTO_FRAG)."""
        import math as _m
        from random_image_viewer.drawing import impasto
        s = dict(impasto.DEFAULTS, **(settings or {}))
        az, up = _m.radians(s['light']), impasto.LIGHT_UP
        lx, ly, lz = _m.cos(az) * _m.cos(up), _m.sin(az) * _m.cos(up), _m.sin(up)
        hx, hy, hz = lx, ly, lz + 1.0
        hn = _m.sqrt(hx * hx + hy * hy + hz * hz)
        return {'bump': 4.2 * s['depth'] / 100.0 * max(0.3, k), 'detail': 0.25 + 0.9 * s['grooves'] / 100.0,
                'edges': 1.2 * s['edges'] / 100.0, 'gloss': 1.6 * s['gloss'] / 100.0,
                'occl': 3.0 * s['depth'] / 100.0 + 0.5,
                'L': (lx, ly, lz), 'Hv': (hx / hn, hy / hn, hz / hn)}

    def _canvas_lit(self, layer, image, k):
        """⛰ *layer*'s image lit as impasto, once per change of its paint or
        settings - not for every zoom. From its thickness map (see
        _update_height) where there is one: only where it changed."""
        from random_image_viewer.drawing import impasto
        hm = getattr(layer, 'height_map', None)
        if hm is not None and hm['canvas'] == (image.cacheKey() >> 32):
            key = ('h', hm['serial'], image.cacheKey(), impasto.settings_key(layer.impasto), round(k, 5))
            kept = layer.impasto_lit
            if kept is not None and kept[0] == key:
                return kept[1]
            # (what changed since it was last lit is gathered in 'dirty' until
            # it is lit again: None after a whole new map - then all of it)
            same = (kept is not None and kept[0][0] == 'h' and kept[0][3:] == key[3:]
                    and hm.get('dirty') is not None)
            lit = impasto.light_height(image, hm['image'], layer.impasto, k,
                                       boxes=hm['dirty'] if same else None,
                                       into=kept[1] if same else None)
            hm['dirty'] = []                # lit up to here: from now on, only what changes
            layer.impasto_lit = (key, lit, image)
            return lit
        key = (image.cacheKey(), impasto.settings_key(layer.impasto), round(k, 5))
        kept = layer.impasto_lit
        if kept is not None and kept[0] == key:
            return kept[1]
        if not getattr(self, '_impasto_gpu_set', False):
            self._impasto_gpu_set = True
            gpu = getattr(self, 'gpu_processor', None)
            try:
                if gpu is not None and gpu.is_available():
                    impasto.use_gpu(gpu)
            except Exception as e:
                print(f"⛰ Impasto: no GPU ({e}), on the CPU")
        lit = impasto.light(image, layer.impasto, k)
        layer.impasto_lit = (key, lit, image)
        return lit

    def _layer_image(self, layer, device, view, raw=False):
        """*layer* as a transparent image for this view: its picture-sized
        image (see _layer_canvas) drawn to the view, the guides over it.
        *raw*: its paint alone, as it is kept - not lit, no guides."""
        marks = list(self._ordered_marks(layer))
        paint = [(kind, m) for kind, m in marks if not self._is_guide(kind, m)]
        guides = [] if raw else [(kind, m) for kind, m in marks if self._is_guide(kind, m)]
        canvas, rect, k = self._layer_canvas(layer, paint)
        lit = bool(layer.impasto) and not raw
        source = self._canvas_lit(layer, canvas, k) if lit else canvas
        out = QImage(device.width(), device.height(), QImage.Format_ARGB32_Premultiplied)
        out.fill(Qt.transparent)
        p = QPainter(out)
        p.setRenderHint(QPainter.SmoothPixmapTransform, True)
        to_picture = QTransform()
        to_picture.translate(rect.x(), rect.y())
        to_picture.scale(1.0 / k, 1.0 / k)
        p.setTransform(to_picture * self._layer_view_transform(view))
        p.drawImage(0, 0, source)
        p.resetTransform()
        if guides:
            self._paint_layer_marks(p, guides, *view)
        p.end()
        if lit:
            if self._prelit is None or len(self._prelit) > 64:
                self._prelit = set()
            self._prelit.add(out.cacheKey())        # already lit: not again at screen size
        return out

    _RASTER_STEPS = 12                  # images kept per layer for undo ...
    _RASTER_STEPS_BYTES = 200 << 20     # ... and at most this much memory for all of them
    _STEPS_NEAR_END = 4                 # a whole-drawing lay keeps the images before its last few marks
    _STEPS_EVERY = 8                    # ... and one every this many marks further back

    def _keeps_step_at(self, done, total):
        """Whether laying a whole drawing keeps its image at *done* of
        *total* marks: so undo after a zoom or turn is a copy plus a few
        marks, however far back it goes (within _RASTER_STEPS)."""
        left = total - done
        return done > 0 and left > 0 and (left <= self._STEPS_NEAR_END or left % self._STEPS_EVERY == 0)

    def _keep_raster_step(self, layer, key, marks, count, image):
        """Keep *image* - *layer*'s first *count* marks, for *key* - for undo."""
        if key and key[0] == 'canvas':
            return      # a layer's own image: undo puts patches back (see _keep_patch)
        steps = [s for s in layer.raster_steps if s['key'] == key and s['count'] != count]
        steps.append({'key': key, 'count': count, 'last': marks[count - 1][1], 'image': image.copy()})
        steps.sort(key=lambda s: s['count'])
        steps = steps[-self._RASTER_STEPS:]
        layer.raster_steps = steps
        total = sum(s['image'].sizeInBytes() for layer_ in self.layers for s in layer_.raster_steps)
        while total > self._RASTER_STEPS_BYTES and steps:
            total -= steps.pop(0)['image'].sizeInBytes()    # the oldest go first

    def _raster_step_for(self, layer, key, marks):
        """The kept image with the most of *marks* in it (all of them still
        there, nothing after them yet), or None."""
        best = None
        for step in layer.raster_steps:
            count = step['count']
            if (step['key'] == key and 0 < count <= len(marks)
                    and marks[count - 1][1] is step['last']
                    and (best is None or count > best['count'])):
                best = step
        return best

    _BUSY_SYNC_S = 0.3      # work that keeps the app busy longer than this shows the busy line

    def _lay_marks(self, layer, image, marks, done, view, key):
        """Paint marks[done:] onto *image*. A long run (a whole drawing after
        a zoom or undo) goes a mark at a time: it keeps the images before
        its last few marks (the next undos are a copy), and once it has
        taken a while the busy line at the bottom shows how far it got."""
        todo = len(marks) - done
        if todo <= 2:
            painter = QPainter(image)
            self._paint_layer_marks(painter, marks[done:], *view)
            painter.end()
            return
        started = time.perf_counter()
        busy = getattr(self, '_busy_line', None)
        shown = False
        try:
            for i in range(done, len(marks)):
                if i > done and self._keeps_step_at(i, len(marks)):
                    self._keep_raster_step(layer, key, marks, i, image)
                painter = QPainter(image)
                self._paint_layer_marks(painter, marks[i:i + 1], *view)
                painter.end()
                if busy is not None and time.perf_counter() - started > self._BUSY_SYNC_S:
                    busy.show_progress((i + 1 - done) / todo)
                    busy.repaint()              # the app is busy: draw it now
                    shown = True
        finally:
            if shown and getattr(self, '_settle_job', None) is None:
                busy.hide()

    def _brush_erasing(self):
        """True while the brush is in 🧽 Erase mode."""
        return getattr(self, 'brush_settings', {}).get('mode') == 'erase'

    _pen_eraser_end = False     # the pen's eraser end is the one in use
    _pen_mode_back = None       # ... and the mode its tip was in

    def pen_end_changed(self, eraser):
        """The pen turned round. Its eraser end puts the brush in 🧽 Erase
        mode (with Erase's own size); the tip end brings back the mode it
        was in. Only while free drawing, and never in the middle of a stroke
        - it is picked up on the next event after."""
        if eraser == self._pen_eraser_end:
            return
        if not getattr(self, 'free_draw_mode', False) or self.is_drawing_free_stroke:
            return
        self._pen_eraser_end = eraser
        if eraser:
            if self._brush_erasing():
                self._pen_mode_back = None      # already erasing: leave it so
                return
            self._pen_mode_back = self.brush_settings['mode']
            self.set_brush_mode('erase')
        else:
            back, self._pen_mode_back = self._pen_mode_back, None
            if back in brushes.MODES and back != 'erase' and self._brush_erasing():
                self.set_brush_mode(back)
        self._sync_erase_button()

    def _live_rub_image(self, device):
        """The 🧽 erase brush stroke being drawn, as laid on screen so far -
        for _paint_marks to take out of the active layer - or None."""
        if not (getattr(self, 'is_drawing_free_stroke', False) and self._brush_erasing()):
            return None
        image = getattr(self, '_stroke_image', None)
        if image is None or image.isNull() or device is None:
            return None
        if image.width() != device.width() or image.height() != device.height():
            return None
        return image

    def _paint_erase_stroke(self, painter, stroke, to_display, scale_x):
        """Clear an erase stroke's band out of a layer's own image.

        A round-cap pen is solid and safe against self-overlap (back-and-forth
        drags), and being painted in draw order, whatever is drawn afterwards
        stays on top of the hole.
        """
        if not stroke:
            return
        from PySide6.QtGui import QPolygonF
        pts = [QPointF(*to_display(x, y)) for x, y, _ in stroke]
        radius = max(1.0, max(r for _, _, r in stroke) * scale_x)
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setCompositionMode(QPainter.CompositionMode_Clear)
        if len(pts) == 1:
            # Single tap: a dot
            painter.setPen(Qt.NoPen)
            painter.setBrush(Qt.black)
            painter.drawEllipse(pts[0], radius, radius)
        else:
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(Qt.black, radius * 2.0, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            painter.drawPolyline(QPolygonF(pts))
        painter.restore()

    def _paint_layer_marks(self, painter, marks, canvas_width, canvas_height, original_size,
                           scale_x, scale_y, offset_x=0, offset_y=0):
        """Paint ``(kind, mark)`` pairs onto *painter*, in the order they were drawn.

        Draw order is chronological rather than grouped by type, so a fill laid
        down after a line covers it, and a line drawn after a fill sits on top.
        """
        to_display = self._mark_display_mapper(
            original_size, scale_x, scale_y, offset_x, offset_y)
        rot = self.rotation_angle
        # Ruler lines span the whole picture, so they have no second coordinate
        # to map - they need the unrotated extents directly (see the mapper).
        if rot in (90, 270):
            unrot_w, unrot_h = original_size.height(), original_size.width()
        else:
            unrot_w, unrot_h = original_size.width(), original_size.height()
        pen = QPen(self.line_color, self.line_thickness, Qt.SolidLine)
        hidden = self._sel_hidden       # ⬚ marks being transformed show on their own
        guide_off = self._studio_guide_offset()
        if guide_off:
            marks = self._with_studio_guides(marks, guide_off, hidden)

        guides = self.guides_visible
        tick = self._export_tick if self._exporting else self._lay_tick      # 💾 progress
        for kind, mark in marks:
            if tick is not None:
                tick()
            if hidden and id(mark) in hidden:
                continue
            if not guides and self._is_guide(kind, mark):
                continue                # 👁 off: the guides alone are hidden
            if kind == 'free_stroke' and getattr(mark, 'clip', None) and id(mark) not in self._clip_busy:
                # A shape run over with the brush: kept inside the shape.
                from PySide6.QtGui import QPainterPath
                outline = QPainterPath()
                outline.addPolygon(QPolygonF([
                    QPointF(*to_display(*((p.x(), p.y()) if isinstance(p, QPointF) else p[:2])))
                    for p in mark.clip]))
                painter.save()
                painter.setClipPath(outline, Qt.IntersectClip)
                self._clip_busy.add(id(mark))
                try:
                    self._paint_layer_marks(painter, ((kind, mark),), canvas_width, canvas_height,
                                            original_size, scale_x, scale_y, offset_x, offset_y)
                finally:
                    self._clip_busy.discard(id(mark))
                    painter.restore()
                continue
            if (kind == 'free_stroke' and getattr(mark, 'erase', False)
                    and painter.compositionMode() != QPainter.CompositionMode_DestinationOut):
                # 🧽 An erase stroke: laid exactly like any brush stroke, but
                # what it lays takes paint away (its alpha: soft tips, low
                # opacity and light pressure rub out less).
                painter.save()
                painter.setCompositionMode(QPainter.CompositionMode_DestinationOut)
                self._paint_layer_marks(painter, ((kind, mark),), canvas_width, canvas_height,
                                        original_size, scale_x, scale_y, offset_x, offset_y)
                painter.restore()
                continue
            if kind in ('line', 'hline'):
                # Ruler lines carry the size and colour they were placed with
                # (see RulerLine); bare numbers from older code follow the pen.
                width_ = getattr(mark, 'thickness', None) or self.line_thickness
                if not self._exporting:
                    width_ = self._line_window_width(width_, self._pixel_ratio(painter))
                line_pen = QPen(getattr(mark, 'color', None) or self.line_color,
                                width_ * self._export_pen_scale, Qt.SolidLine)
            if kind == 'line':
                # A ruler line spans the whole picture, so it has no second
                # coordinate to map - under 90/270 it becomes a horizontal one.
                tx = (unrot_w - mark) if self.flipped_h else mark
                if rot == 90:
                    dy = int(tx * scale_y) + offset_y
                    if 0 <= dy < canvas_height:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(0, dy, canvas_width, dy)
                elif rot == 180:
                    dx = int((unrot_w - tx) * scale_x) + offset_x
                    if 0 <= dx < canvas_width:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(dx, 0, dx, canvas_height)
                elif rot == 270:
                    dy = int((unrot_w - tx) * scale_y) + offset_y
                    if 0 <= dy < canvas_height:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(0, dy, canvas_width, dy)
                else:
                    dx = int(tx * scale_x) + offset_x
                    if 0 <= dx < canvas_width:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(dx, 0, dx, canvas_height)

            elif kind == 'hline':
                ty = (unrot_h - mark) if self.flipped_v else mark
                if rot == 90:
                    dx = int((unrot_h - ty) * scale_x) + offset_x
                    if 0 <= dx < canvas_width:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(dx, 0, dx, canvas_height)
                elif rot == 180:
                    dy = int((unrot_h - ty) * scale_y) + offset_y
                    if 0 <= dy < canvas_height:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(0, dy, canvas_width, dy)
                elif rot == 270:
                    dx = int(ty * scale_x) + offset_x
                    if 0 <= dx < canvas_width:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(dx, 0, dx, canvas_height)
                else:
                    dy = int(ty * scale_y) + offset_y
                    if 0 <= dy < canvas_height:
                        painter.setRenderHint(QPainter.Antialiasing, False)
                        painter.setPen(line_pen)
                        painter.drawLine(0, dy, canvas_width, dy)

            elif kind == 'free_line':
                if mark is self.__dict__.get('_grad_held'):
                    continue        # 🌈 a handle being dragged: the preview shows it
                if mark.get('stars'):
                    self._paint_star_fill(painter, mark, to_display,
                                          QColor(mark.get('color') or self.line_color))
                    continue
                if mark.get('gradient'):
                    self._paint_gradient_line(painter, mark, to_display, self._line_pen_width(mark, painter))
                    continue
                sx_, sy_ = to_display(*mark['start'])
                ex_, ey_ = to_display(*mark['end'])
                tolerance = 10
                if (max(sx_, ex_) >= -tolerance and min(sx_, ex_) <= canvas_width + tolerance
                        and max(sy_, ey_) >= -tolerance and min(sy_, ey_) <= canvas_height + tolerance):
                    width_ = self._line_pen_width(mark, painter)

                    def line_(p, c, a=((sx_, sy_), (ex_, ey_)), w=width_):
                        p.setRenderHint(QPainter.Antialiasing, True)
                        p.setPen(QPen(c, w, Qt.SolidLine))
                        p.drawLine(*self._hairline_points(p, a, w))
                        p.setRenderHint(QPainter.Antialiasing, False)
                    if mark.get('jitter'):
                        # 🎲 a colour per stamp / streak / speck (_mark_jitter)
                        self._paint_jittered(painter, mark, to_display,
                                             QColor(mark.get('color') or self.line_color),
                                             [mark['start'], mark['end']], width_, line_)
                    else:
                        line_(painter, mark.get('color') or self.line_color)

            elif kind == 'free_stroke':
                if getattr(mark, 'stamps', None):
                    view = self._picture_to_display(to_display, unrot_w, unrot_h)
                    render = getattr(mark, 'render', None)
                    on_screen = painter.worldTransform().isIdentity() and not self._exporting
                    shift = _shift_between(render[0], view) if render is not None and on_screen else None
                    if shift is not None:
                        # The stroke as last laid, at this scale and turn: the
                        # same pixels, at most moved (a pan) - no laying it all
                        # again. Just drawn, it is the live render itself.
                        painter.drawImage(render[2] + shift, render[1])
                        continue
                    if (render is not None and on_screen and self._canvas_k is not None
                            # (🧽 an erase stroke from the GPU brush too: its rub
                            # as drawn, taken out - laying all the hairs again
                            # cost ~200 ms at the pen-up)
                            and (not getattr(mark, 'erase', False) or getattr(mark, 'gpu_render', False))
                            and self._burn_render(painter, mark, render, view)):
                        continue
                    tint = getattr(mark, 'history', None)
                    picture = self._history_picture() if tint is not None else None
                    made = brushes.paint_stamps(
                        painter, brushes.load_texture(mark.texture), mark.stamps,
                        view, (canvas_width, canvas_height), flat=getattr(mark, 'flat', False),
                        history=(picture, tint) if picture is not None else None)
                    if made is not None and made[2] and on_screen:
                        mark.render = (QTransform(view), made[0], made[1])
                    continue
                if len(mark) < 2:
                    continue
                # Honour the antialiasing toggle for brush strokes. The old
                # code only consulted it on untransformed images and forced it
                # on once anything was rotated; this keeps one answer.
                # Size and colour come from the stroke itself when it carries
                # them, so editing the brush never restyles older strokes.
                base = (getattr(mark, 'thickness', None) or self.line_thickness) * self._export_pen_scale
                if self._canvas_k is not None:
                    # Into a layer image: the width the stroke had on screen
                    # when drawn, in picture pixels (older strokes: as at the
                    # fitted view), so it zooms with the paint.
                    width = getattr(mark, 'pic_width', None)
                    base = (width if width else base / self._canvas_fit) * self._canvas_k
                ink = getattr(mark, 'color', None) or self.line_color
                smooth = bool(self.line_antialiasing) and base > 1
                painter.setRenderHint(QPainter.Antialiasing, smooth)
                painter.setRenderHint(QPainter.SmoothPixmapTransform, smooth)
                if ink.alpha() == 255:
                    self._draw_pen_stroke(painter, mark, to_display, base, ink)
                else:
                    # See-through ink, as paint: the stroke drawn solid once,
                    # then laid down at the ink's opacity. Drawn piece by
                    # piece, every overlap of the round-ended pieces built
                    # up, so a stroke at 10 % came out all but opaque.
                    self._draw_see_through_stroke(painter, mark, to_display, base, ink, smooth)
                painter.setRenderHint(QPainter.Antialiasing, False)

            elif kind == 'fill':
                self._paint_one_fill(painter, mark, to_display)

            elif kind == 'image':
                self._paint_snapshot(painter, mark, to_display, unrot_w, unrot_h)

            elif kind == 'erase':
                self._paint_erase_stroke(painter, mark, to_display, scale_x)

        painter.setPen(pen)

    _clip_busy = set()          # strokes being painted inside their clip (see _paint_layer_marks)

    def _brush_mode_for_marks(self):
        """The brush mode lines and shapes take - whichever is chosen, but
        Paint - or None: they lay their colour. (A tick box could switch
        this off: lost unseen, Push then drew plain rectangles.)"""
        mode = self.brush_settings.get('mode', 'paint')
        return mode if mode != 'paint' and mode in brushes.MODES else None

    def _brush_along(self, path, clip=None, report=None):
        """Run the brush (its mode, tip, size) along *path* (picture points)
        as one stroke - as if drawn with a perfectly steady hand. *clip*: an
        outline (picture points) the result is kept inside. True when it
        left a mark."""
        path = [(float(p[0]), float(p[1])) for p in path]
        if len(path) < 2 or not self.current_image:
            return False
        scale = self._view_scale()
        step = max(2.0, 0.25 * float(self.line_thickness)) / scale      # picture px
        points = [path[0]]
        for (x0, y0), (x1, y1) in zip(path, path[1:]):
            n = max(1, int(math.hypot(x1 - x0, y1 - y0) / step))
            points += [(x0 + (x1 - x0) * i / n, y0 + (y1 - y0) * i / n) for i in range(1, n + 1)]
        settings = self.brush_settings
        steady = settings.get('smoothing')
        settings['smoothing'] = 0          # its corners where they are
        images, strokes = len(self.drawn_images), len(self.drawn_free_strokes)
        # Taken by the mark as it is made (end_free_draw_stroke /
        # _bake_blend_stroke), so it is never laid outside the shape.
        self._pending_clip = [tuple(p[:2]) for p in clip] if clip else None
        try:
            self.start_free_draw_stroke(points[0][0], points[0][1], 1.0)
            if not self.is_drawing_free_stroke:
                return False
            count = len(points) - 1
            for i, (x, y) in enumerate(points[1:]):
                self.add_free_draw_point(x, y, 1.0)
                if report is not None:
                    report(0.92 * (i + 1) / count, "brushing")
            if report is not None:
                report(0.93, "laying it into the layer")
            self.end_free_draw_stroke()
        finally:
            settings['smoothing'] = steady
            self._pending_clip = None
        return (len(self.drawn_images) > images or len(self.drawn_free_strokes) > strokes)

    def _clip_image_mark(self, mark, clip):
        """A kept-pixels mark (Blend / Smear / Push: see _bake_blend_stroke)
        cut to the outline *clip* (picture points): outside it, nothing."""
        image = mark['image']
        (x0, y0), (x1, y1), (x2, y2) = [tuple(c[:2]) for c in mark['corners'][:3]]
        w, h = image.width(), image.height()
        to_picture = QTransform((x1 - x0) / w, (y1 - y0) / w, (x2 - x0) / h, (y2 - y0) / h, x0, y0)
        to_image, ok = to_picture.inverted()
        if not ok:
            return
        mask = QImage(image.size(), QImage.Format_ARGB32_Premultiplied)
        mask.fill(Qt.transparent)
        p = QPainter(mask)
        p.setRenderHint(QPainter.Antialiasing, True)
        p.setPen(Qt.NoPen)
        p.setBrush(QColor(0, 0, 0))
        p.drawPolygon(QPolygonF([to_image.map(QPointF(x, y)) for x, y in clip]))
        p.end()
        # A push's cut with it: left whole, it took away the paint outside
        # the shape wherever the brush had swept.
        for part in ('image', 'cut'):
            if mark.get(part) is None:
                continue
            clipped = mark[part].convertToFormat(QImage.Format_ARGB32_Premultiplied)
            p = QPainter(clipped)
            p.setCompositionMode(QPainter.CompositionMode_DestinationIn)
            p.drawImage(0, 0, mask)
            p.end()
            mark[part] = clipped

    def _mode_tool_hint(self):
        """A line or shape tool is in hand with the brush in a mode: say
        what it will do, and where colour is."""
        mode = self._brush_mode_for_marks()
        if mode is not None:
            self.status.showMessage(
                f"{mode.capitalize()}: the brush runs along the line / over the inside of the shape - "
                "switch the brush to Paint for colour, gradient or stars", 6000)

    def _brush_over_shape(self, outline):
        """Run the brush over the whole shape *outline* (picture points):
        back and forth in rows half a brush apart, along its longer way,
        kept inside the shape - a lasso in Blend softens just that area,
        in Erase cuts it out."""
        pts = [(float(p[0]), float(p[1])) for p in outline]
        a = math.radians(self._shape_angle(pts))
        ca, sa = math.cos(a), math.sin(a)
        uv = [(x * ca + y * sa, -x * sa + y * ca) for x, y in pts]
        v_lo, v_hi = min(v for _, v in uv), max(v for _, v in uv)
        # A brush far smaller than the shape runs it in hundreds of rows: a
        # 1 px Push over a hand-sized lasso was minutes of work for next to
        # nothing to see. At least so wide that it takes _SHAPE_ROWS rows.
        across = (v_hi - v_lo) * self._view_scale()                     # screen px
        size = max(float(self.line_thickness), 2.0 * across / self._SHAPE_ROWS)
        self._shape_run_size = round(size)
        spacing = max(1.0, 0.5 * size) / self._view_scale()
        rows = max(1, int(math.ceil((v_hi - v_lo) / spacing)))
        first = v_lo + ((v_hi - v_lo) - (rows - 1) * spacing) / 2
        path = []
        edges = list(zip(uv, uv[1:] + uv[:1]))
        for r in range(rows):
            v = first + r * spacing
            cuts = sorted(u0 + (v - v0) * (u1 - u0) / (v1 - v0)
                          for (u0, v0), (u1, v1) in edges
                          if (v0 <= v < v1) or (v1 <= v < v0))
            spans = [(cuts[i], cuts[i + 1]) for i in range(0, len(cuts) - 1, 2)]
            if r % 2:
                spans = [(b, c) for c, b in reversed(spans)]
            for u_from, u_to in spans:
                path += [(u_from, v), (u_to, v)]
        if len(path) < 2:
            return False
        path = [(u * ca - v * sa, u * sa + v * ca) for u, v in path]
        # As much brushing as covering the shape by hand: a second or a few
        # for a big shape in Smear / Push - say so meanwhile.
        mode = self.brush_settings.get('mode', '')
        own = self.line_thickness
        wider = round(size) > own
        self.line_thickness = max(1, round(size))       # (for this run: the size slider keeps its own)
        try:
            with self._working(f"Brushing the shape — {mode.capitalize()}") as card:
                made = self._brush_along(path, clip=pts, report=card.set)
        finally:
            self.line_thickness = own
        note = (f" with a {round(size)} px brush - {own} px is too small for a shape" if wider else "")
        self.status.showMessage(
            f"Shape run over in {mode.capitalize()}{note} — Ctrl+Z to undo" if made
            else "Nothing to work on inside the shape", 6000 if wider else 3000)
        return made

    _SHAPE_ROWS = 24        # a shape is run in at most this many rows (see _brush_over_shape)

    def _line_kind(self, mark):
        """A new free line / polyline (dict): paint, with its width in
        picture px as drawn now, or a guide - by 'Lines are paint'."""
        if self.brush_settings.get('lines_paint', True):
            mark['guide'] = False
            width = self._line_window_width(mark.get('thickness', self.line_thickness))
            mark['pic_width'] = width / self._view_scale()
        else:
            mark['guide'] = True

    def _line_window_width(self, thickness, ratio=None):
        """A line of *thickness* in window px, where there are *ratio* real
        pixels to one (the screen's, 1.5 at 150 %): half such a pixel or so
        less, at every size alike, so 1 is one pixel of the screen - it was
        1.5 of them, smeared over two to five."""
        if ratio is None:
            try:
                ratio = float(self.image_label.devicePixelRatioF())
            except Exception:
                ratio = 1.0
        if ratio <= 1.0 or thickness < 1:
            return float(thickness)
        return thickness - (1.0 - 1.0 / ratio)

    @staticmethod
    def _pixel_ratio(painter):
        """Real pixels to one of *painter*'s: the GPU canvas's 1.5 at 150 %,
        an image's 1."""
        try:
            return float(painter.device().devicePixelRatioF()) or 1.0
        except Exception:
            return 1.0

    def _hairline_points(self, painter, points, width):
        """*points* (painter coords) as QPointF - for a line about a pixel
        wide on pixel centres: between two (where whole-number coords put
        it), it came out as two rows at half strength."""
        out = [QPointF(p) if hasattr(p, 'x') else QPointF(*p) for p in points]
        world = painter.worldTransform() * QTransform.fromScale(*[self._pixel_ratio(painter)] * 2)
        if width * math.sqrt(abs(world.determinant())) > 1.3:
            return out
        back, ok = world.inverted()
        if not ok:
            return out
        snapped = []
        for p in out:
            q = world.map(p)
            snapped.append(back.map(QPointF(math.floor(q.x() + 1e-6) + 0.5, math.floor(q.y() + 1e-6) + 0.5)))
        return snapped

    def _line_pen_width(self, mark, painter=None):
        """The pen width of a free line or polyline (a dict) on this device:
        a guide keeps its screen width; one painted into a layer image keeps
        its width in picture px (pic_width), so it zooms with the paint -
        never under one pixel of that image (a fainter, greyer line)."""
        width = mark.get('thickness') or self.line_thickness
        if self._canvas_k is not None:
            return max(1.0, (mark.get('pic_width') or width / self._canvas_fit) * self._canvas_k)
        if painter is not None and not self._exporting:
            width = self._line_window_width(width, self._pixel_ratio(painter))
        return width * self._export_pen_scale

    def _draw_pen_stroke(self, painter, mark, to_display, base, ink):
        """A round-pen stroke (points with pressure) in *ink*: runs of one
        width go down as one polyline, a C++ call instead of one per piece."""
        run = [QPoint(*to_display(mark[0][0], mark[0][1]))]
        run_width = None
        for i in range(len(mark) - 1):
            a, b = mark[i], mark[i + 1]
            ap = a[2] if len(a) == 3 else 1.0
            bp = b[2] if len(b) == 3 else 1.0
            thickness = self._pressure_to_thickness((ap + bp) / 2.0, base)
            if len(run) > 1 and thickness != run_width:
                painter.setPen(QPen(ink, run_width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
                painter.drawPolyline(self._hairline_points(painter, run, run_width) if run_width <= 1 else run)
                run = run[-1:]
            run_width = thickness
            run.append(QPoint(*to_display(b[0], b[1])))
        painter.setPen(QPen(ink, run_width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        # (a 1 px pen on pixel centres too, see _hairline_points)
        painter.drawPolyline(self._hairline_points(painter, run, run_width) if run_width <= 1 else run)

    def _draw_see_through_stroke(self, painter, mark, to_display, base, ink, smooth):
        """*mark* in see-through *ink*: solid on an image of its own (just
        the box it covers), laid on *painter* at the ink's opacity."""
        pts = [to_display(p[0], p[1]) for p in mark]
        reach = max(base * 1.5, 1.0) / 2.0 + 2         # pressure can widen it to 150 %
        xs, ys = [p[0] for p in pts], [p[1] for p in pts]
        box = QRectF(min(xs) - reach, min(ys) - reach,
                     max(xs) - min(xs) + 2 * reach, max(ys) - min(ys) + 2 * reach)
        world = painter.worldTransform()
        device = painter.device()
        area = world.mapRect(box).toAlignedRect().intersected(
            QRect(0, 0, device.width(), device.height()))
        if area.isEmpty():
            return
        layer = QImage(area.size(), QImage.Format_ARGB32_Premultiplied)
        layer.fill(Qt.transparent)
        lp = QPainter(layer)
        lp.setWorldTransform(world * QTransform.fromTranslate(-area.x(), -area.y()))
        lp.setRenderHint(QPainter.Antialiasing, smooth)
        solid = QColor(ink)
        solid.setAlpha(255)
        self._draw_pen_stroke(lp, mark, to_display, base, solid)
        lp.end()
        painter.save()
        painter.resetTransform()
        painter.setOpacity(painter.opacity() * ink.alphaF())
        painter.drawImage(area.topLeft(), layer)
        painter.restore()

    def _studio_guide_offset(self):
        """◧ Studio: where the picture starts on the sheet (picture px), for
        the guides copied onto the canvas - None when there are none to copy
        (Studio off, or laying marks for a file: the copies are a drawing
        aid, the saved picture keeps only what was drawn)."""
        if not self.studio_mode or self._exporting or not self.current_image:
            return None
        base = self.pixmap_cache.get(self.current_image)
        if base is None or base.isNull():
            return None
        return self._studio_offset(base)

    @staticmethod
    def _with_studio_guides(marks, off, hidden=None):
        """*marks*, each guide drawn on the picture followed by a copy at the
        same place on the canvas: vertical ruler lines, free lines and
        polylines - lines to measure against while painting what you see.
        Horizontal ruler lines span both sides already. A guide reaching
        onto the canvas is left as it is. Copies, made as they are painted:
        moving, undoing or hiding the guide takes its copy with it."""
        def shifted(p):
            if isinstance(p, QPointF):
                return QPointF(p.x() - off, p.y())
            return (p[0] - off, *p[1:])

        def x_of(p):
            return p.x() if isinstance(p, QPointF) else p[0]

        for kind, mark in marks:
            yield kind, mark
            if hidden and id(mark) in hidden:
                continue
            if kind == 'line':
                if float(mark) >= off:
                    yield kind, (RulerLine(float(mark) - off, getattr(mark, 'thickness', None),
                                           getattr(mark, 'color', None))
                                 if isinstance(mark, RulerLine) else mark - off)
            elif not (isinstance(mark, dict) and mark.get('guide', True)):
                continue            # a line painted into the picture: not a guide to copy
            elif kind == 'free_line':
                if min(x_of(mark['start']), x_of(mark['end'])) >= off:
                    copy = dict(mark)
                    copy['start'], copy['end'] = shifted(mark['start']), shifted(mark['end'])
                    if mark.get('gradient'):
                        g = mark['gradient']
                        copy['gradient'] = dict(g, start=shifted(g['start']), end=shifted(g['end']))
                    yield kind, copy
            elif kind == 'fill' and mark.get('shape') == 'polyline':
                points = mark.get('points') or []
                if points and min(x_of(p) for p in points) >= off:
                    copy = dict(mark)
                    copy['points'] = [shifted(p) for p in points]
                    if mark.get('gradient'):
                        g = mark['gradient']
                        copy['gradient'] = dict(g, start=shifted(g['start']), end=shifted(g['end']))
                    yield kind, copy

    @staticmethod
    def _picture_to_display(to_display, unrot_w, unrot_h):
        """*to_display* as a QTransform, so it can be inverted and carry
        whole images. It is affine (scale, flip, quarter turns, offset), so
        where it sends three corners of the picture pins it down."""
        x0, y0 = to_display(0, 0)
        xw, yw = to_display(unrot_w, 0)
        xh, yh = to_display(0, unrot_h)
        return QTransform((xw - x0) / unrot_w, (yw - y0) / unrot_w,
                          (xh - x0) / unrot_h, (yh - y0) / unrot_h, x0, y0)

    def _paint_snapshot(self, painter, snap, to_display, unrot_w, unrot_h):
        """A 📸 snapshot: its image stretched between where its top-left,
        top-right and bottom-left corners now land."""
        image = snap['image']
        t = self._picture_to_display(to_display, unrot_w, unrot_h)
        p0, p1, p2 = (t.map(QPointF(x, y)) for x, y in snap['corners'])
        w, h = image.width(), image.height()
        painter.save()
        painter.setTransform(QTransform((p1.x() - p0.x()) / w, (p1.y() - p0.y()) / w,
                                        (p2.x() - p0.x()) / h, (p2.y() - p0.y()) / h,
                                        p0.x(), p0.y()), True)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        cut = snap.get('cut')
        if cut is not None:
            # \U0001F9CA a push that replaces: the layer's paint taken out where
            # it went, then its pushed paint laid in (what was moved away
            # - or the empty canvas pushed in - is gone from there)
            painter.save()
            painter.setCompositionMode(QPainter.CompositionMode_DestinationOut)
            painter.drawImage(0, 0, cut)
            painter.restore()
            # ... added, not laid over: the pushed paint carries the mask in
            # it already. Laid over, that took the layer's paint away a second
            # time wherever the mask is partly in (its resampled edge, a brush
            # under 100 %) - outlines round every hair, see-through to below.
            painter.setCompositionMode(QPainter.CompositionMode_Plus)
        painter.drawImage(0, 0, image)
        painter.restore()

    def _push_paint(self, size):
        """The active layer's own paint in the view, for a push on it alone
        to keep. What that push reads and shows is the layer as seen - faded
        by its opacity, lit, guides on - and kept like that it went through
        all of it a second time. None where the two are the same."""
        layer = self.active_layer
        if not layer.visible or not layer.has_content():
            return None
        if (layer.opacity == 100 and not layer.impasto
                and not any(self._is_guide(k, m) for k, m in self._ordered_marks(layer))):
            return None
        view = (size.width(), size.height(), *self._fx_view_params())
        return self._layer_image(layer, QImage(size, QImage.Format_ARGB32_Premultiplied), view, raw=True)

    def _backdrop_view(self, size):
        """The view without the active layer and those above it - the
        picture (or the canvas colour) and the layers under it - for a push
        on this layer alone to show what it uncovers. None when it cannot."""
        try:
            index = self.layers.index(self.active_layer)
            allowed = {id(layer) for layer in self.layers[:index]}
            allowed.add(id(self._under_sheet))
            params = self._fx_view_params()
            if self.image_visible and getattr(self, 'original_pixmap', None) is not None:
                view = self._scale_pixmap(self.original_pixmap, self.current_image)
            else:
                view = QPixmap(self.image_label.size())
                view.fill(self.canvas_color)
            if view.size() != size:
                return None
            painter = QPainter(view)
            self._paint_marks(painter, view.width(), view.height(), *params,
                              which=lambda layer: id(layer) in allowed)
            painter.end()
            return view.toImage()
        except Exception as e:
            print(f"_backdrop_view: {e}")
            return None

    def _paint_one_fill(self, painter, fill, to_display, antialias=True):
        """Paint a single filled shape (lasso / rectangle / ellipse), or a
        polyline (the polygon tool's outline-only sibling)."""
        if fill is self.__dict__.get('_grad_held'):
            return      # 🌈 a handle being dragged: shown by the drag preview instead
        points = fill.get('points') or []
        color = QColor(fill.get('color', self.line_color))
        alpha = fill.get('alpha')
        if alpha is not None:
            color.setAlpha(int(alpha))
        if fill.get('stars') and (len(points) >= 3 or fill['stars'].get('band')):
            self._paint_star_fill(painter, fill, to_display, color)
            return
        if (fill.get('fill_tip') and len(points) >= 3 and fill.get('shape') != 'polyline'
                and self._paint_texture_fill(painter, fill, to_display, antialias)):
            return          # 🖌 through the brush's tip
        if fill.get('gradient') and fill.get('shape') == 'polyline':
            self._paint_gradient_line(painter, dict(fill, color=color), to_display,
                                      self._line_pen_width(fill, painter), antialias)
            return
        if fill.get('gradient') and len(points) >= 3:
            self._paint_gradient_fill(painter, fill, to_display, color, antialias)
            return
        if fill.get('jitter') and len(points) >= 2:
            # 🎲 a colour per stamp / streak / speck (_mark_jitter): the shape
            # drawn solid, coloured by its pattern.
            plain = {k: v for k, v in fill.items() if k not in ('jitter', 'alpha')}
            reach = (self._line_pen_width(fill, painter)
                     if fill.get('shape') == 'polyline' else 1.0)
            self._paint_jittered(painter, fill, to_display, color, points, reach,
                                 lambda p, c: self._paint_one_fill(p, dict(plain, color=c), to_display, antialias))
            return
        if fill.get('shape') == 'polyline':
            if len(points) < 2:
                return
            painter.setRenderHint(QPainter.Antialiasing, antialias)
            painter.setBrush(Qt.NoBrush)
            width = self._line_pen_width(fill, painter)
            painter.setPen(QPen(color, width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            corners = QPolygonF(self._hairline_points(
                painter, [to_display(x, y) for x, y in points], width))
            if fill.get('closed'):
                painter.drawPolygon(corners)
            else:
                painter.drawPolyline(corners)
            painter.setRenderHint(QPainter.Antialiasing, False)
            return
        if len(points) < 3:
            return
        painter.setRenderHint(QPainter.Antialiasing, antialias)
        painter.setPen(Qt.NoPen)
        painter.setBrush(color)
        # Every shape is stored as an outline in image coordinates — rectangles
        # and ellipses are flattened to points when committed — so one polygon
        # draw covers all of them and they transform like any other mark.
        painter.drawPolygon([QPoint(*to_display(x, y)) for x, y in points])
        painter.setBrush(Qt.NoBrush)
        painter.setRenderHint(QPainter.Antialiasing, False)

    def _fast_line_update(self):
        """Fast path to redraw only lines over current displayed image using GPU if available.
        Falls back to full display_image if prerequisites missing.
        Assumes self.current_image is path to original image file."""
        try:
            if not self.current_image:
                return
            if not (self.has_marks()):
                return
            if not self.lines_visible:
                return
            if self.__dict__.get('_gpu_display'):
                self.display_image(self.current_image)      # 🎮 the label's frame is not what shows
                return
            # Semi-transparent lines cannot use the incremental overlay path:
            #   • the GPU kernel overwrites pixels (ignoring alpha), and
            #   • painting onto the already-drawn pixmap double-blends existing
            #     lines.
            # Render from the clean base image in a single pass so every line
            # (new and existing) reflects the current transparency level.
            if getattr(self, 'line_transparency', 255) < 255:
                self.display_image(self.current_image)
                return
            # Erased marks, layer opacity and blend modes: the fast overlay path
            # paints onto the already-drawn pixmap, so they would pile up.
            if not self._layers_plain() or self.current_erase_stroke:
                self.display_image(self.current_image)
                return
            # Get currently displayed pixmap (may already have LUT/enhancements applied)
            current_pixmap = self._view_pixmap()
            if (not current_pixmap) or current_pixmap.isNull():
                # Fallback: full redraw
                self.display_image(self.current_image)
                return
            # Every mark carries its own size and colour, and the GPU overlay
            # kernel paints all of them with one pen (and drops strokes and
            # fills), so marks are always composited with the CPU painter below.
            # A handful of lines costs well under a millisecond there.
            # CPU fallback: manually paint over current_pixmap copy
            overlay = current_pixmap.copy()
            painter = QPainter(overlay)
            # Default to no antialiasing (vertical/horizontal lines remain crisp).
            painter.setRenderHint(QPainter.Antialiasing, False)
            painter.setPen(QPen(self.line_color, self.line_thickness, Qt.SolidLine))
            tx = self._compute_line_transform()
            if tx:
                scale_x = tx['scale_x']; scale_y = tx['scale_y']
                draw_x = tx['draw_x']; draw_y = tx['draw_y']
                if overlay.width() == tx['zoomed_width'] and overlay.height() == tx['zoomed_height']:
                    offset_x = 0; offset_y = 0
                else:
                    offset_x = draw_x; offset_y = draw_y
                
                # Get original size for transformation calculations
                original_size = self.original_pixmap.size() if hasattr(self, 'original_pixmap') and self.original_pixmap else QSize(1, 1)
                
                # Apply coordinate transformations based on rotation and flips
                # One painter for every mark type, in creation order.
                self._paint_marks(painter, overlay.width(), overlay.height(),
                                  original_size, scale_x, scale_y, offset_x, offset_y)
            else:
                # Fallback simple proportional scaling when transform computation fails
                if hasattr(self, 'original_pixmap') and self.original_pixmap:
                    original_size = self.original_pixmap.size()
                else:
                    original_size = current_pixmap.size()
                scale_x = current_pixmap.width() / original_size.width() if original_size.width() else 1.0
                scale_y = current_pixmap.height() / original_size.height() if original_size.height() else 1.0
                self._paint_marks(painter, overlay.width(), overlay.height(),
                                  original_size, scale_x, scale_y, 0, 0)
            painter.end()
            overlay = self._apply_fixed_overlays_to_pixmap(overlay)
            self.image_label.setPixmap(overlay)
        except Exception as e:
            print(f"_fast_line_update failed: {e}; skipping line overlay to prevent loops")
            # DO NOT call display_image here as it can cause infinite loops with rotation + LUT
            # Instead, just skip the line overlay and let the current image display without lines
    # ...existing code...
    def __init__(self):
        super().__init__()
        self.setFocusPolicy(Qt.StrongFocus)
        self.setWindowTitle("Ova Viewer")
        self.setGeometry(100, 100, 1200, 760)
        # Accept touch events at the top-level window so Qt does not discard
        # them before they reach the ImageLabel child widget.
        self.setAttribute(Qt.WA_AcceptTouchEvents, True)
        
        # Set window icon
        self.set_window_icon()
        
        # Enable drag and drop for folders
        self.setAcceptDrops(True)
        
        self.folder = None
        self.images = []            # Browsing list AFTER the file-type filter
        self._all_items = []        # Every scanned item, before filtering
        self._hidden_types = set()  # Extensions hidden via the File Types panel
        # Add mode (➕): opening / dropping adds to the list instead of replacing it
        self.add_to_playlist_mode = False
        self._scan_append = False
        self._type_filter_window = None
        self._type_filter_window_pos = None  # session-only memory of last drag pos
        self.history = []
        self.current_image = None
        self.current_index = -1
        self.history_index = -1  # NEW: For navigation

        # PDF on-demand state
        self._pdf_doc = None   # PdfDocument instance when viewing a PDF
        self._pdf_page = 0     # current 0-based page number
        self._pdf_name = ""

        # PDF high-resolution zoom state: when the user zooms into a PDF page we
        # re-render just that page (or the current 2/3-page spread) at a higher
        # resolution (on a background thread) so small text stays sharp instead
        # of upscaling a blurry raster. Images are untouched.
        self._pdf_hires_page = -1      # anchor page currently loaded at hi-res (-1 = none)
        self._pdf_hires_count = 1      # spread page-count of the current hi-res render
        self._pdf_hires_target = 0     # target size (long edge / composite height) px
        self._pdf_hires_thread = None  # active PdfHiresWorker, if any
        self._pdf_hires_timer = QTimer(self)
        self._pdf_hires_timer.setSingleShot(True)
        self._pdf_hires_timer.setInterval(180)
        self._pdf_hires_timer.timeout.connect(self._start_pdf_hires_render)

        # PDF spread (book) view: "single" | "2page" | "3page". Persisted via
        # QSettings so the user's preferred reading layout survives restarts.
        from PySide6.QtCore import QSettings
        self._settings = QSettings("OvaViewer", "RandomImageViewer")
        mode = self._settings.value("pdf_spread_mode", "single")
        if mode not in ("single", "2page", "3page"):
            mode = "single"
        self._pdf_spread_mode = mode

        # EPUB on-demand state
        self._epub_doc = None  # EpubDocument instance when viewing an EPUB
        self._epub_page = 0    # current 0-based page number
        self._epub_name = ""

        # CBR/CBZ on-demand state (comic-book archives)
        self._cbr_doc = None   # CbrDocument instance when viewing a comic archive
        self._cbr_page = 0     # current 0-based page number
        self._cbr_name = ""
        
        # Performance optimization: Cache management for large collections
        self.pixmap_cache = {}  # Cache for loaded pixmaps
        self.max_cache_size = 20  # Increased cache size for better performance with large collections
        self.scaled_cache = {}  # Cache for scaled versions
        self.last_size = None  # Track resize events
        self.resize_timer = QTimer()
        self.resize_timer.setSingleShot(True)
        self.resize_timer.timeout.connect(self._delayed_resize)
        self.resize_timer.setInterval(50)  # 50ms delay for resize debouncing
        
        # Line drawing functionality
        self.line_drawing_mode = False
        self.horizontal_line_drawing_mode = False
        self.free_line_drawing_mode = False  # New: Free line drawing mode
        self.free_draw_mode = False  # NEW: Free draw mode (continuous drawing)
        self.is_drawing_free_stroke = False  # Track if currently drawing a free stroke
        # 💉 Color Snap (eyedropper) tool state
        self.color_snap_mode = False
        self._color_snap_preview = None  # Lazy-created ColorSnapPreview widget
        self._color_snap_last_label_pos = None  # Sampled point in label coords (for overlay connector)
        self._color_snap_last_color = None  # Last sampled QColor (for overlay connector)
        # Snap palette: persisted swatches of colors picked via 💉 or ✨ auto-extract.
        # Stored as ROWS — each ✨ extract creates a new row; 💉 clicks append to
        # the most-recent row. Global dedup across all rows.
        self.snapped_rows = []  # list[list[str]]
        self.snapped_rows_max = 10  # FIFO cap on number of rows
        # Floating palette window (lazy-created), persistent until user hits ✕.
        self._snap_palette_window = None
        self._snap_palette_window_pos = None  # session-only memory of last drag pos
        # Floating Curves (RGB levels) window (lazy-created).
        self._curves_window = None
        self._curves_window_pos = None  # session-only memory of last drag pos
        # Cached source QImage for fast sampling (rebuilt on current_image change)
        self._color_snap_src_image = None
        self._color_snap_src_key = None
        # Debounce: only sample hover after cursor has been still for HOVER_MS
        self._color_snap_hover_ms = 350
        self._color_snap_hover_timer = QTimer(self)
        self._color_snap_hover_timer.setSingleShot(True)
        self._color_snap_hover_timer.timeout.connect(self._on_color_snap_hover_timeout)
        self._color_snap_pending_label_pos = None
        self._color_snap_pending_global_pos = None
        
        # ⚡ PERFORMANCE: Real-time drawing optimization
        self.drawing_cache = None  # Cache converted coordinates and display data
        self.temp_stroke_overlay = None  # Temporary overlay for real-time drawing
        self.last_draw_point = None  # Track last painted point for incremental drawing
        
        # ⚡ ULTRA-FAST: Timer-based updates for true real-time performance.
        # Free-draw paints onto a cached overlay (cheap, no per-event image reload),
        # so it can refresh almost immediately for low-latency pen feedback. The
        # eraser freeze was a separate issue (fixed via its own coord cache), so a
        # fast interval here is safe.
        self.stroke_update_timer = QTimer(self)
        self.stroke_update_timer.setSingleShot(True)
        self.stroke_update_timer.timeout.connect(self._update_display_with_overlay)
        self.stroke_update_timer.setInterval(8)  # ~120 FPS steady refresh during strokes; low latency, input-flood-safe
        self.drawn_lines = []  # List of x positions for vertical lines
        self.drawn_horizontal_lines = []  # List of y positions for horizontal lines
        self.drawn_free_lines = []  # List of free lines, each with start and end points
        self.drawn_free_strokes = []  # NEW: List of free draw strokes (continuous paths)
        # Filled shapes (lasso / rectangle / ellipse), each an outline in image
        # coordinates. Painted by _paint_marks in creation order like any mark.
        self.drawn_fills = []
        self.fill_mode = None          # None | 'lasso' | 'polygon' | 'polyline' | 'rect' | 'ellipse' | 'triangle'
        self.current_fill = None       # shape being dragged out / polygon being placed
        self._polygon_hover_pos = None # last pointer position while placing a polygon
        self._fill_to_screen = None     # image -> widget mapping, fixed for one drag
        self._fill_input_cache = None   # widget -> image geometry for the drag
        self._fill_input_sig = None     # (image, view) that geometry was built for
        self._fill_view_sig = None      # the view state that mapping was built for
        self._fill_screen_pts = []      # outline in widget coords, built incrementally
        # 🧽 Eraser tool: partial pixel-erase of the drawing/line layer (never the image).
        # Each stroke is a list of (x, y, radius) points in ORIGINAL image coords;
        # radius is stored in original-image px so erased holes stay anchored under zoom.
        self.eraser_mode = False
        self.eraser_size = 20  # Eraser diameter in screen px (range 1-30)
        self.erase_strokes = []  # List[List[(x, y, radius)]]
        # For each committed erase stroke, snapshot how many free strokes/lines existed
        # at that moment. Drawings added AFTER the most recent erase are kept visible
        # inside erase holes, so you can draw again over an erased area.
        self._undo_stack = []  # Chronological record: 'line'|'hline'|'free_line'|'free_stroke'|'erase'

        # Marks live in layers, bottom to top. The lists above are always the
        # active layer's own lists (see _bind_layer).
        self.layers = [Layer("Layer 1")]
        self._layer_count = 1               # for naming new layers
        self._bind_layer(self.layers[0])
        self._layer_window = None
        self._layer_window_pos = None
        self.canvas_color = QColor(self._settings.value("canvas_color", "#000000"))
        if not self.canvas_color.isValid():
            self.canvas_color = QColor(Qt.black)
        self._canvas_popup = None
        self._canvas_popup_pos = None
        self._layer_redraw_timer = QTimer(self)
        self._layer_redraw_timer.setSingleShot(True)
        self._layer_redraw_timer.setInterval(30)
        self._layer_redraw_timer.timeout.connect(self._redraw_layers)
        self.current_erase_stroke = None  # Stroke being drawn
        self.is_erasing = False  # Track if currently erasing
        self.eraser_cache = None  # Precomputed coord-mapping geometry during a stroke
        # ⚡ Coalesce high-frequency tablet/mouse erase points into ~60 FPS redraws
        # so a fast drag doesn't fire a full display_image per event and freeze.
        self.erase_update_timer = QTimer(self)
        self.erase_update_timer.setSingleShot(True)
        self.erase_update_timer.setInterval(16)
        self.erase_update_timer.timeout.connect(self._flush_erase_update)
        self.current_line_start = None  # Store first click point for free line
        self._line_preview_base = None  # Snapshot pixmap for free-line rubber-band preview
        self._line_preview_geom = None  # Geometry cache for the preview
        self._line_preview_pending_pos = None  # Latest pen pos awaiting render
        # ⚡ Throttle the free-line preview to ~60 FPS (tablet-event-rate safe)
        self.line_preview_timer = QTimer(self)
        self.line_preview_timer.setSingleShot(True)
        self.line_preview_timer.setInterval(16)
        self.line_preview_timer.timeout.connect(self._flush_line_preview)
        self.current_stroke = None  # NEW: Current stroke being drawn
        self._stroke_base = None    # the view under the stroke being drawn
        self._fx_live = None        # (under, over) for a stroke drawn under the effects
        self._view_in_motion = False    # zoom / pan under way: marks follow cheaply
        self._touch_pan = None          # Wacom two-finger pan, see _start_touch_pan
        QTimer.singleShot(0, self._start_touch_pan)
        # a stroke left open by a release the canvas never got (see _StrokeEndWatch)
        self._stroke_end_watch = _StrokeEndWatch(self)
        QApplication.instance().installEventFilter(self._stroke_end_watch)
        self._settle_wanted = {}        # layer id -> (w, h, view) to lay once it rests
        self._settle_job = None
        self._blend_under = None    # Blend: what is under the stroke, as Sample reads it
        self.is_drawing = False  # NEW: Track if currently drawing a stroke
        self.lines_visible = True  # New: Toggle line visibility
        self.image_visible = True  # New: Toggle image visibility
        # The canvas under the picture (a QColor, or None): the sheet that
        # shows where the picture is while the picture is hidden - the
        # stack is Background, Canvas, Picture, then the layers. Goes with
        # the drawing (see clear_lines).
        self.under_canvas = None
        self.under_canvas_visible = True    # its tick in 📚 (it is there once made)
        # ◧ Studio: a blank canvas the picture's size beside it, on the left,
        # to paint a copy of what is on the right (see _studio_sheet). It
        # stays on from picture to picture until switched off.
        self.studio_mode = False
        self._studio_kept = None    # (picture's cacheKey, sheet, picture's x on it)
        # The picture layer's own look (🖼 Picture in 📚): mixed into the
        # canvas under it, or the background, like any layer into its below.
        self.picture_opacity = 100
        self.picture_blend = 'Normal'
        self._under_sheet = Layer("Canvas")
        self._sketch_hid_picture = False    # new sketch hid it: shown again with the drawing gone
        self.line_thickness = 5  # Default line thickness (increased for better pen pressure visibility)
        self.line_color = QColor("#FFFFFF")  # Default white color
        self.line_transparency = 255  # Line transparency (0=fully transparent, 255=fully opaque)
        self.line_color.setAlpha(self.line_transparency)  # Set initial transparency
        self.line_antialiasing = True  # Enable antialiasing for smoother lines
        self.performance_mode = True  # NEW: Performance mode toggle (True = fast, False = quality)
        self.pen_pressure_enabled = True  # 🎨 NEW: Pen pressure sensitivity toggle
        self._current_pressure = 1.0  # 🎨 NEW: Current pressure value for real-time painting
        self._tablet_pressure = 1.0  # 🎨 NEW: Stored tablet pressure for mouse event compatibility
        self._last_pressure = 1.0  # 🎨 NEW: Last pressure for smoothing interpolation
        self._tablet_tilt = None    # (xTilt, yTilt) of the last tablet event ...
        self._tablet_tilt_time = 0.0   # ... and when, so a mouse later doesn't inherit it
        # 🖌 Brush tip: Round, or a PNG texture with its settings (remembered)
        self.brush_settings = dict(brushes.DEFAULT_SETTINGS)
        try:
            self.brush_settings.update(json.loads(self._settings.value("brush_settings", "{}")))
        except (TypeError, ValueError):
            pass
        # Each line tool and the brush keep their own size (see _recall_tool_size).
        try:
            self._tool_sizes = {k: int(v) for k, v in
                                json.loads(self._settings.value("tool_sizes", "{}")).items()}
        except (TypeError, ValueError, AttributeError):
            self._tool_sizes = {}
        try:
            self.brush_textures = [p for p in json.loads(self._settings.value("brush_textures", "[]"))
                                   if os.path.isfile(p)]
        except (TypeError, ValueError):
            self.brush_textures = []
        if (self.brush_settings['texture'] and self.brush_settings['texture'] not in (brushes.BRISTLES, brushes.DUST, brushes.SPRAY, brushes.RAKE, brushes.SOFT, brushes.HAIRS)
                and not os.path.isfile(self.brush_settings['texture'])):
            self.brush_settings['texture'] = ''
        self._brush_window = None
        self._brush_window_pos = None
        # 🐧 ColorPenguin sends the colour picked there (Rebelle's WebSocket
        # port); started after the window is up, see _start_colour_sync.
        self._colour_sync = None
        QTimer.singleShot(1500, self._start_colour_sync)
        # Floating panels hide while another program is in front (see _on_app_state).
        self._panels_hidden_for_away = []
        QApplication.instance().applicationStateChanged.connect(self._on_app_state)
        # 🟥 The colour swatch comes back if it was open when the app closed.
        QTimer.singleShot(1600, lambda: self.toggle_colour_swatch(True)
                          if str(self._settings.value("colour_swatch_open", "false")).lower()
                          in ("true", "1") else None)
        self._stamp_trail = None    # the textured stroke being drawn
        self._flat_live = None      # its buffers, when it does not build up
        # Fixed overlay tools (non-interactive, passive overlays over the image)
        self.crosshair_overlay = False  # Draw cross lines at image center
        # ▦ composition grids (drawing/comp_grids): {key: orient} of the ones on,
        # any number at once; remembered. grid_overlay: any of them on.
        self._comp_grids = self._load_comp_grids()
        self._grid_points = self._load_grid_points()     # ▦ moved vanishing points
        self._comp_grid_opacity = self._settings_int("comp_grid_opacity", 80, 10, 100)
        self.grid_overlay = bool(self._comp_grids)
        self._grids_window = None
        # Pen each guide was switched on with (see _guide_pen); None = off
        self._crosshair_pen = None
        self._grid_pen = None
        # Always on top functionality
        self.always_on_top = False

        # Fullscreen functionality
        self.is_fullscreen = False
        self.normal_geometry = None  # Store window geometry before fullscreen

        # Image enhancement parameters
        self.grayscale_value = 0  # 0 = color, 100 = full grayscale
        self.contrast_value = 50  # 50 = normal, -130 to 200 range
        self.gamma_value = 0     # 0 = normal, -200 to +500 range
        self.value_filter_enabled = False  # Posterize to N grayscale tones (value study)
        self.value_levels = 4              # Number of value levels when posterize is enabled (2-10)
        self.value_filter_opacity = 100    # Blend over the original (0-100, 100=full effect)
        # Color Groups (palette quantization) - flat color fields from the image's own colors
        self.color_groups_enabled = False  # Reduce image to N dominant colors (color map)
        self.color_groups_count = 8        # Number of palette colors (2-32)
        self.color_groups_field = 0        # Field-size pre-smoothing to merge regions (0=off, 0-20)
        self.color_groups_opacity = 100    # Blend over the original (0-100, 100=full effect)
        self._color_palette_cache = {}     # Cache computed palettes keyed by image+params
        # Object Groups (cryptomatte-style) - segment into regions, flatten each
        # to its own local colour (spatial separation, unlike Color Groups)
        self.object_groups_enabled = False   # Toggle the per-object flattening
        self.object_groups_detail = 45       # Region granularity (0-100, higher=more objects)
        self.object_groups_min_size = 12     # Minimum region size (0-100, higher=fewer specks)
        self.object_groups_mode = "local"    # local | id | local_edges
        self.object_groups_opacity = 100     # Blend over the original (0-100, 100=full effect)

        # Floating per-effect settings panels (created lazily, like Curves)
        self._effect_windows = {}
        self._effect_window_pos = {}
        # Edge detection (Canny "plane change" filter)
        self.edge_detection_enabled = False  # Toggle Canny edge detection
        self.edge_mode = "white_on_black"    # white_on_black | black_on_white | overlay
        self.edge_sensitivity = 50           # 0-100, drives Canny thresholds
        self.edge_opacity = 100              # Blend over the original (0-100, 100=full effect)
        # Form Lines - cross-contour line work inferred from shading
        self.form_lines_enabled = False       # Toggle the form-line render
        self.form_lines_mode = "contour"      # contour | hatch | wrap
        self.form_lines_density = 50          # 0-100: line count / stroke density
        self.form_lines_smooth = 45           # 0-100: surface texture ignored before reading form
        self.form_lines_opacity = 100         # Blend over the original (0-100, 100=full effect)
        self.form_lines_over_image = False    # Draw on the photo instead of on white paper
        # Edge line color override. None = each mode's default (white on dark,
        # black on light, line color over image). Set by the line-color tools.
        self.edge_color = None
        # Curves (classical RGB levels) - per-channel black/white/midtone tone curve
        self.curves_enabled = False          # Toggle the curves effect
        self.curves_channel = "master"       # Active channel being edited (master/r/g/b)
        self.curves_black = {"master": 0, "r": 0, "g": 0, "b": 0}     # Black point (0-254)
        self.curves_white = {"master": 255, "r": 255, "g": 255, "b": 255}  # White point (1-255)
        self.curves_gamma = {"master": 0, "r": 0, "g": 0, "b": 0}     # Midtone slider (-100..100, 0=neutral)
        self.curves_opacity = 100            # Effect opacity/strength (0-100, 100=full)
        self.rotation_angle = 0   # Rotation angle in degrees
        self.flipped_h = False    # Horizontal flip state
        self.flipped_v = False    # Vertical flip state
        self.original_pixmap = None  # Cache original image for fast processing
        self.enhancement_cache = {}  # Cache enhanced versions
        
        # LUT (Look-Up Table) support
        self.current_lut = None   # Currently loaded LUT data
        self.current_lut_name = "None"  # Name of current LUT
        self.lut_folder = None    # Folder containing CUBE LUT files
        self.lut_files = []       # List of available LUT files
        self.lut_strength = 100   # LUT application strength (0-100%)
        self.lut_cache = {}       # Cache for loaded LUTs to avoid reloading
        # Separate enable flag so a selected LUT can be temporarily disabled without clearing selection
        self.lut_enabled = False
        # Track whether cached last processed image contained LUT so we don't reuse it when disabled
        self._last_processed_has_lut = False
        
        # GPU acceleration - initialized lazily on first use to avoid 30s startup delay
        self.gpu_processor = GPULutProcessor()

        # Autoplay-on-end: advance to the next item when a video or animated
        # GIF finishes, so clips play back to back. Off by default.
        self.autoplay_next_enabled = False
        self.loop_media_enabled = False   # repeat the clip instead of ending it
        self._autoplay_advancing = False   # re-entrancy guard while switching
        self._gif_prev_frame = -1          # last GIF frame seen (loop detection)
        self._gif_started_at = 0.0         # monotonic time the GIF pass began

        # Dub audio: play a sibling audio file (clip.mp4 -> clip.mp3) instead
        # of the video's own track. Off by default — it costs a sibling-file
        # lookup per video and a second media player while one is playing.
        self.dub_audio_enabled = False

        # Playback is suspended while the window sits minimised in the taskbar
        # and picked up again on restore (see changeEvent).
        self._was_minimized = False
        self._paused_by_minimize = False

        # Video playback state
        self._video_playing = False
        self._video_muted = True   # Videos start silent; unmuting sticks for the session
        self._video_volume = 50  # 0-100

        # Subtitle (.srt) state for video playback
        self._subtitles_enabled = True       # show subtitles when available
        self._subtitle_cues = []             # list of (start_ms, end_ms, text)
        self._subtitle_starts = []           # cached start times for bisect lookup
        self._subtitle_path = None           # loaded .srt path (or None)
        self._current_subtitle_text = ""     # cue text at the current position
        self._video_last_scaled = None       # last scaled frame (pre-subtitle) for redraw

        self.timer_interval = 5  # seconds
        self.timer_remaining = 0
        self._auto_advance_active = False
        self._timer_paused = False  # NEW: Timer pause state

        self.timer = QTimer(self)
        self.timer.setInterval(1000)

        # ✂ Crop: the frame is kept as 0..1 fractions of the picture as shown,
        # so it follows zoom, pan and window resizes untouched.
        self.crop_mode = False
        self._crop_sel = None               # QRectF, or None with no frame yet
        self._crop_path = None              # the picture the frame was drawn on
        self._crop_drag = None              # (grabbed part, frame at press, press pos)

        # Frame playback: ⚡ in fps units plays the folder's pictures, in
        # alphabetical order, as a film (see _start_frame_playback).
        self._fps_mode = False
        self._frame_cache = None            # FrameCache, made on first use
        self._frame_paths = []              # the pictures being played, in order
        self._frame_index = -1              # index into _frame_paths on screen
        self._frame_count = 0               # frames advanced since play started (never wraps)
        self._frame_anchor = (0.0, 0)       # (clock time, _frame_count) the film is timed from
        self._frame_box = QSize()           # size frames are decoded at
        self._frame_shown_path = None
        self._frame_last_pixmap = None      # last frame after effects, before fitting
        self._frame_status_time = 0.0
        self._frame_timer = QTimer(self)
        self._frame_timer.setTimerType(Qt.PreciseTimer)
        self._frame_timer.timeout.connect(self._on_frame_tick)

        # Sorting mode for navigation
        self.random_mode = False  # Default to alphabetical order
        
        # Store original window flags for UI toggle
        self.original_window_flags = None
        
        # Window dragging and resizing for frameless mode
        self.dragging = False
        self.drag_start_position = None
        self.resizing = False
        self.resize_edge = None
        self.resize_margin = 10  # Pixel margin for resize detection
        self.timer.timeout.connect(self._on_timer_tick)

        self.init_ui()
        # Initial window: big enough that the Brush panel and the Layers
        # panel under it fit down the left side of the canvas - within the
        # screen, centred on it.
        try:
            w, h = 1450, 1060
            screen = QApplication.primaryScreen()
            if screen is not None:
                avail = screen.availableGeometry()
                w = min(w, avail.width() - 40)
                h = min(h, avail.height() - 72)     # room for the title bar
                self.resize(w, h)
                self.move(avail.x() + max(0, (avail.width() - w) // 2),
                          avail.y() + max(0, (avail.height() - h - 32) // 2))
            else:
                self.resize(w, h)
        except Exception as _e:
            pass
        
        # Store original window flags for UI toggle functionality
        self.original_window_flags = self.windowFlags()
        
        # Force layout evaluation after initial resize
        QTimer.singleShot(0, self._delayed_resize)
        # Auto-set default LUT folder if present
        # NOTE: trailing backslash in a raw string would escape the quote -> syntax error
        self.default_lut_path = r"V:\LUTS"
        if os.path.isdir(self.default_lut_path):
            self.lut_folder = self.default_lut_path
            try:
                self.lut_files = self.scan_lut_folder(self.default_lut_path)
                if hasattr(self, 'lut_combo') and self.lut_files:
                    # Populate using the same display-name format as
                    # update_lut_combo (forward slashes, no .cube extension) so
                    # the combo text matches what apply_selected_lut expects.
                    self.update_lut_combo()
                    self.current_lut_name = "None"
                print(f"Default LUT folder loaded: {self.default_lut_path} ({len(self.lut_files)} files)")
            except Exception as e:
                print(f"Failed loading default LUT folder {self.default_lut_path}: {e}")

    def tabletEvent(self, event):
        """Forward tablet events to the ImageLabel for proper pressure handling"""
        if hasattr(self, 'image_label') and self.image_label:
            # Forward the tablet event to the ImageLabel
            self.image_label.tabletEvent(event)

    def set_window_icon(self):
        """Set the window icon from available icon files"""
        try:
            import os
            import sys
            
            # Determine the correct path for icon files
            if getattr(sys, 'frozen', False):
                # Running as PyInstaller executable
                base_path = sys._MEIPASS  # PyInstaller's temporary folder
                print(f"Running as executable, looking for icons in: {base_path}")
            else:
                # Running as Python script - icons are in project root
                base_path = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
                print(f"Running as script, looking for icons in: {base_path}")
            
            icon_loaded = False
            
            # Try different icon formats in order of preference
            icon_files = [
                ("icon.svg", "SVG"),
                ("icon.png", "PNG"), 
                ("icon.ico", "ICO")
            ]
            
            for filename, format_name in icon_files:
                icon_path = os.path.join(base_path, filename)
                print(f"Trying icon path: {icon_path}")
                if os.path.exists(icon_path):
                    icon = QIcon(icon_path)
                    if not icon.isNull():
                        self.setWindowIcon(icon)
                        print(f"✅ Window icon loaded from {format_name}: {filename}")
                        icon_loaded = True
                        break
                else:
                    print(f"❌ Icon not found: {icon_path}")
            
            if not icon_loaded:
                print("ℹ️ No icon file found (tried: icon.svg, icon.png, icon.ico)")
                
        except Exception as e:
            print(f"⚠️ Failed to load window icon: {e}")
            import traceback
            traceback.print_exc()

    def init_ui(self):
        # 🎨 Enable tablet tracking on main window for proper pressure support
        self.setTabletTracking(True)
        self.setAttribute(Qt.WA_TabletTracking, True)

        # Create main toolbar — Qt's native overflow ('»') button appears
        # automatically when items don't fit at the current window width,
        # giving access to clipped icons via a popup.
        self.main_toolbar = QToolBar("Main Toolbar")
        self.main_toolbar.setIconSize(QSize(20, 20))
        self.addToolBar(Qt.TopToolBarArea, self.main_toolbar)
        self.main_toolbar.setMovable(False)
        # Right padding keeps the last icon clear of the native overflow
        # ('»') button when the bar is narrow.
        self.main_toolbar.setStyleSheet("QToolBar { spacing: 4px; padding-right: 24px; }")

        # Force a toolbar break to ensure next toolbar goes on new line
        self.addToolBarBreak(Qt.TopToolBarArea)

        # Create secondary toolbar for sliders (initially hidden) - this will be BELOW main toolbar
        self.slider_toolbar = QToolBar("Slider Toolbar")
        self.slider_toolbar.setIconSize(QSize(20, 20))
        self.addToolBar(Qt.TopToolBarArea, self.slider_toolbar)
        self.slider_toolbar.setMovable(False)
        self.slider_toolbar.setStyleSheet("QToolBar { spacing: 4px; padding-right: 24px; background: #2a2d30; border-top: 1px solid #35383b; }")
        self.slider_toolbar.setMinimumHeight(32)
        self.slider_toolbar.setMaximumHeight(40)
        self.slider_toolbar.hide()

        # Track which mode we're in. Lowered threshold (was 1500) so the
        # second row appears earlier and fewer icons get hidden behind the
        # native '»' overflow popup at common window widths.
        # Track which mode we're in. Threshold raised (was 1100) so the
        # second row appears before any icon would overflow into the
        # native '»' popup, which is hard to keep open on hover-out.
        self.two_row_mode = False
        self.width_threshold = 1600

        # Setup main toolbar with all controls
        self._setup_main_toolbar()
        
        # Setup enhancement controls on BOTH toolbars permanently
        self._setup_enhancement_controls()

        # Keep the toolbar overflow ('»') popup open for 2 seconds after
        # the cursor leaves it, so the user has time to come back.
        self._install_popup_persistence()

        # Central widget and layout setup
        central_splitter = QSplitter(Qt.Horizontal)
        self.setCentralWidget(central_splitter)

        image_widget = QWidget()
        image_widget.setTabletTracking(True)
        image_widget.setAttribute(Qt.WA_TabletTracking, True)
        image_layout = QVBoxLayout(image_widget)
        image_layout.setContentsMargins(6, 6, 6, 6)

        self.image_label = ImageLabel("Open a folder to start\n(double-click here, or drop a folder)")
        self.image_label.parent_viewer = self
        self.image_label.setAlignment(Qt.AlignCenter)
        self.image_label.setScaledContents(False)
        self.image_label.setMinimumSize(400, 400)
        self.image_label.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.image_label.setToolTip("")
        # 🎮 Zoom / pan drawn on the graphics card, in a window of its own laid
        # over the canvas (see GpuView, _gpu_frame) - made on the first zoom.
        self._gpu_view = None
        self._gpu_view_tried = False

        image_layout.addWidget(self.image_label)
        image_widget.setLayout(image_layout)
        central_splitter.addWidget(image_widget)

        # Semi-transparent overlay shown while a PDF is being rendered
        self._pdf_overlay = PdfLoadingOverlay(self.image_label)

        # Floating video controls overlay (appears on hover)
        self._video_overlay = VideoControlsOverlay(self.image_label)
        self._video_overlay.set_viewer(self)

        self.history_list = QListWidget()
        self.history_list.setMaximumWidth(180)
        self.history_list.itemClicked.connect(self.on_history_clicked)
        self.history_list.hide()
        central_splitter.addWidget(self.history_list)
        central_splitter.setSizes([900, 100])

        self.status = QStatusBar()
        self.setStatusBar(self.status)
        # The size grip reserves a bottom-right corner that nudges permanent
        # widgets upward; disabling it lets them sit vertically centered.
        self.status.setSizeGripEnabled(False)

        # Left end: ⟲ (fit the picture to the window) and the zoom in % of
        # the picture's real size. Then the messages - in a label of their
        # own: a status bar hides whatever sits on its left while it shows a
        # message, and the app shows one at nearly every step.
        zoom_box = QWidget()
        zoom_row = QHBoxLayout(zoom_box)
        zoom_row.setContentsMargins(4, 0, 6, 0)
        zoom_row.setSpacing(2)
        self.zoom_reset_btn = QToolButton()
        self.zoom_reset_btn.setText("⟲")
        self.zoom_reset_btn.setAutoRaise(True)
        self.zoom_reset_btn.setToolTip("Real size: 100 %, one picture pixel per screen pixel. "
                                       "Click again to fit the window (Ctrl+0 fits too)")
        self.zoom_reset_btn.setCursor(Qt.PointingHandCursor)
        self.zoom_reset_btn.clicked.connect(lambda: self.zoom_actual_size())
        zoom_row.addWidget(self.zoom_reset_btn)
        self.zoom_label = QLabel("")
        self.zoom_label.setToolTip("Zoom: the picture shown at this % of its real size")
        self.zoom_label.setStyleSheet("QLabel { color: #b8bcc0; font-size: 10px; min-width: 38px; }")
        zoom_row.addWidget(self.zoom_label)
        self.status.addWidget(zoom_box)
        self._status_text = QLabel("")
        self._status_text.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Preferred)
        self.status.addWidget(self._status_text, 1)
        self._busy_line = _BusyLine(self.status)
        self._status_timer = QTimer(self)
        self._status_timer.setSingleShot(True)
        self._status_timer.timeout.connect(self._status_text.clear)

        def show_message(text, timeout=0):
            self._status_text.setText(text)
            if timeout:
                self._status_timer.start(int(timeout))
            else:
                self._status_timer.stop()

        def clear_message():
            self._status_timer.stop()
            self._status_text.clear()
        self.status.showMessage = show_message
        self.status.clearMessage = clear_message
        self.status.currentMessage = lambda: self._status_text.text()

        # Build/startup readout for developers: deliberately small and dim so
        # it reads as instrumentation rather than UI. Filled in by
        # report_startup_ready() once the window is interactive (the version
        # comes from git, which is too slow to ask during startup).
        self.startup_label = QLabel()
        self.startup_label.setStyleSheet(
            "QLabel { color: #5f6368; font-size: 10px; padding-right: 8px; }")
        self.statusBar().addPermanentWidget(self.startup_label)

        # Which layer the brush is on: a small chip by the file name (click:
